ありがとう石けんのプレゼントもとても素敵でした。','4','/images/enquete/2010/196_wor_f.jpg','/images/enquete/2010/196_wor_dm.gif'],['','/enquete/2010/','197','','naka','建設事業','兵庫県','','','','5','','/images/enquete/2010/197_naka_dm.gif'],['2010/10/20','/enquete/2010/','198','132','oha','製造業','愛知県','458','自信もって他社や他の方へおすすめすることができます。','今回、初めてＤＭを使用し、書類の発送を行いましたが
