御社のＨＰ、ご担当者の手助けによって、スムーズに問題
なく発送することができました。
自信もって他社や他の方へおすすめすることができます。','0','/images/enquete/2010/198_oha_f.jpg','/images/enquete/2010/198_oha_dm.gif'],['','/enquete/2010/','199','','nob','飲食業','千葉県','','','','5','','/images/enquete/2010/199_nob_dm.gif'],['2010/01/01','/enquete/2010/','200','99','comb','プロモーション事業','大阪府','300','どの人の対応もすばらしく、会社として教育がいき渡っていることに感動すらおぼえます。','今年の５月にお願いした●様でとても印象が良かったので、
●様、●様、と続けてお願いさせて頂きました。
どの人の対応もすばらしく、会社として教育がいき渡っていることに感動すらおぼえます。
本当に有難うございました。
加藤様をはじめ、田中様、久野様、梅村様、
そして関わって下さいました皆様、どうぞ今後とも宜しくお願い致します。','5','/images/enquete/2010/200_comb_f.jpg','/images/enquete/2010/200_comb_dm.gif'],['2010/10/12','/enquete/2010/','201','131','mena','コンサルティング事業','愛知県','1019','もっと早くからお願いしていれば良かったです。','今まで自社で行っていたＤＭ発送作業を、
