今まで自社で発送していた時のメール便代と
あまり変わらず、もっと早くからお願いしていれば
良かったです。
今後も毎月お世話になるかと思いますが
どうぞよろしくお願い致します。','5','/images/enquete/2010/201_mena_f.jpg','/images/enquete/2010/201_mena_dm.gif'],['2010/09/30','/enquete/2010/','202','130','act','人材派遣事業','長野県','300','「バカ売れＤＭ集客術」も購入して読みましたが、実践的で大変参考になりました。','ＤＭの発送代行を利用するのは初めてでしたが、
