きめ細かな対応で、安心してお願いできました。
「バカ売れＤＭ集客術」も購入して読みましたが、
実践的で大変参考になりました。','4','/images/enquete/2010/202_act_f.jpg','/images/enquete/2010/202_act_dm.gif'],['2010/09/22','/enquete/2010/','203','129','life','ファイナンシャルプランナー','愛知県','800','是非自分のビジネスにおいても御社の姿勢を参考にさせて頂きたいと思います。','クイックレスポンス・丁寧なご対応ありがとうございました。
自力発送にかかる時間や手間から解放された上に、コストは
