今回、初めて依頼しましたが、その対応の良さから
全く心配なく安心してお任せできました。
今後ともよろしくお願い致します。','5','/images/enquete/2010/207_rei_f.jpg','/images/enquete/2010/207_rei_dm.gif'],['2010/08/23','/enquete/2010/','208','126','tyu','建築関連会社','三重県','2436','まず驚いたのがメールの返信スピードです。これは信頼度と安心感がかなり向上して非常に良いと思いました。','発送コスト削減をずっと考えていたところ、たまたまインターネットで貴社がヒットし、
今回始めてお取引させて頂きました。まず驚いたのがメールの返信スピードです。
これは信頼度と安心感がかなり向上して非常に良いと思いました。進捗状況を
コマメに知らせて頂けるので不安感が全くなく安心してお取引きが出来ました。
また手書きのハガキは貴社からの気持ちが込められていてとても好印象を受けました。
要望ですが、宛名データをお送りする際、メール送信となっておりますが、個人情報の
漏えいの可能性があり不安を感じましたので、今回はCD-Rを郵送させて頂きましたが、
メールでもセキュリティをキチンとかけて送信できる方法を確立して頂ければ尚一層
安心度が増すと思います。今後も取引きを継続したいと思っております。
今回はありがとうございました。','5','/images/enquete/2010/208_tyu_f.jpg','/images/enquete/2010/208_tyu_dm.gif'],['','/enquete/2010/','209','','hiz','薬局','京都府','','','','4','','/images/enquete/2010/209_hiz_dm.gif'],['2010/07/26','/enquete/2010/','210','124','puru','保険会社','茨城県','214','全ての面（例えばこのアンケートシートをとっても）工夫がゆきとどいていることが安心できました。','個人情報の取扱に少し不安も感じながら、オーダーしておりましたが、
