ありがとうございました。','5','/images/enquete/2010/212_iba_f.jpg','/images/enquete/2010/212_iba_dm.gif'],['2010/07/19','/enquete/2010/','213','121','wai','翻訳関連会社','東京都','1150','メール、電話、ハガキ…とコンタクトを密にとって下さり問い合わせから発注まで間があいたのですが、安心感がありました。','初めてＤＭを送るにあたり不安もありましたが、思いのほか
