今後ともどうぞ宜しくお願いいたします。','5','/images/enquete/2010/213_wai_f.jpg','/images/enquete/2010/213_wai_dm.gif'],['2010/07/19','/enquete/2010/','214','120','wai','教育関連','千葉県','4469','代行作業のメニューが豊富であったため、大半をお任せできました。','代行作業のメニューが豊富であったため、大半をお任せできました。
