又、是非使わせて頂きたいと思います。','4','/images/enquete/2010/217_tak_f.jpg','/images/enquete/2010/217_tak_dm.gif'],['2010/05/28','/enquete/2010/','218','115','mzt','復興財団','東京都','884','小口にもかかわらず、たいへん丁寧にご対応いただきました。納期も早く、価格もたいへん安くて良かったです。','小口にもかかわらず、たいへん丁寧にご対応いただきました。
