　感心しました。ありがとー！','4','/images/enquete/2011/222_sgrm_f.jpg','/images/enquete/2011/222_sgrm_dm.jpg'],['2011/06/21','/enquete/2011/','223','164','mic','印刷業','東京都','5026','細かいフォローや発注段階を進むごとに届くハガキなど、御社のゆき届いた対応には他業種ながら勉強させていただきました。','初めて発送代行を利用するにあたって、数社に見積をお願いしました。
