宜しくお願いします。','4','/images/enquete/2011/224_bru_f.jpg','/images/enquete/2011/224_bru_dm.jpg'],['2011/06/10','/enquete/2011/','225','162','con','リサイクル業','福島県','981','担当者がお礼の手紙やメールなど非常に親切な対応で、同じお客様商売として勉強になりました。','PDFで添付できないなど、多少の不安はあったが、
