作業もスムーズで、メールでの報告等もありがたかったです。
今後もぜひ利用させて頂くと共に当社もメディアボックスさんの様な
アフターケアをしっかりできる会社にしていきたいと思いました。
又よろしくお願い致します。','5','/images/enquete/2012/355_myss_f.jpg','/images/enquete/2012/355_myss_dm.jpg'],['2012/08/17','/enquete/2012/','356','247','bsb','冠婚葬祭業','東京都','1736','電話・メールのやりとりなど直ぐに対応していただき、段取り良く進めることができました。','杉山様に対応していただきましたが、電話・メールのやりとりなど
直ぐに対応していただき、段取り良く進めることができました。
ありがとうございました。','4','/images/enquete/2012/356_bsb_f.jpg','/images/enquete/2012/356_bsb_dm.jpg'],['2012/08/17','/enquete/2012/','357','248','int','情報サービス業','東京都','1421','Webでの見積りから発注、発送まで丁寧にご連絡頂き、非常に分かりやすかったです。','Webでの見積りから発注、発送まで丁寧にご連絡頂き、
非常に分かりやすかったです。
また、見積り直後に送られて来たご説明の冊子が非常に良くできており
今回初めてでしたが安心してお願いすることができました。
次回も是非よろしくお願い致します。','5','/images/enquete/2012/357_int_f.jpg','/images/enquete/2012/357_int_dm.jpg'],['2012/09/08','/enquete/2012/','358','249','homk','住宅関連','北海道','851','御社の社会貢献活動に感銘を受けたということがある。','最初の問合せ時から発送完了まで担当者様からこまめに連絡があり、
安心してお任せできた。
また、価格の面でも、初めての利用ということで自社で行った場合と
コスト比較したが労力や時間を考えると安いと思う。
今回利用させて頂いたもうひとつの理由として、
御社の社会貢献活動に感銘を受けたということがある。
私たちが仕事を依頼することが少しでも社会貢献につながるのであれば
これからも使わせて頂きたい。今後は取引先などにも御社のことを紹介したい。','5','/images/enquete/2012/358_homk_f.jpg','/images/enquete/2012/358_homk_dm.jpg'],['','/enquete/2012/','359','','smrd','アパレル会社','東京都','','','','5','/images/enquete/2012/359_smrd_f.jpg','/images/enquete/2012/359_smrd_dm.jpg'],['2012/09/11','/enquete/2012/','360','250','tkok','サービス業','東京都','282','とてもスタッフの対応が良く、安心してお願いすることが出来ました。','今回初めて利用させて頂きましたが、とてもスタッフの対応が良く、
安心してお願いすることが出来ました。次回もぜひ利用させて頂きます。
ありがとうございました。','4','/images/enquete/2012/360_tkok_f.jpg','/images/enquete/2012/360_tkok_dm.jpg'],['2012/09/16','/enquete/2012/','361','251','krg','ホームセンター','山梨県','3879','担当の方が、わかりやすく説明していただいたのでとてもありがたかったです。','担当の方が、わかりやすく説明していただいたので
とてもありがたかったです。
次の機会も使わせていただきます。','4','/images/enquete/2012/361_krg_f.jpg','/images/enquete/2012/361_krg_dm.jpg'],['2012/09/19','/enquete/2012/','362','252','szk','税理士事務所','富山県','4598','こちらの相談も、良心的に対応して頂き金額的に価格の低い方を答えて下さったりと助かりました。','上司から「発送代行の価格比較をしたいので、見積もりをとるように」と指示がありました。
以前から１社を紹介を受けておりましたが、検討したいとのことでした。
数社、見積もり依頼をしました。数社ともすぐに返事がきましたが、御社は後日資料を送ると付け加えてありました。
次の日に届きましたところ、チェックリストに目がいきました。この時点で、ビビッと来たのですが、決定権は上司なので、
全ての資料、全ての見積りを渡しましたところ、一番信頼できそうということで、御社に 決まりました。
こちらの相談も、良心的に対応して頂き金額的に価格の低い方を答えて下さったりと助かりました。
お礼のはがきやメールでの、進捗状況報告など、とても安心できました。ありがとうございました。
ただ、印刷を業者へ依頼されておられるので、日数がかかると感じました。
もう少し早くできるといいです。','4','/images/enquete/2012/362_szk_f.jpg','/images/enquete/2012/362_szk_dm.jpg'],['2012/09/21','/enquete/2012/','363','253','tikk','福祉関連事業','広島県','1400','問い合わせに対する回答が速く丁寧だと感じました。','問い合わせに対する回答が速く
丁寧だと感じました。
価格については、より安い業者さんもありましたが、
この度は早く発送して頂ける御社にお願いして
正解でした。','4','/images/enquete/2012/363_tikk_f.jpg','/images/enquete/2012/363_tikk_dm.jpg'],['2012/09/21','/enquete/2012/','364','254','huzz','不動産業','大阪府','2432','同封して下さった石鹸をとても可愛くてすぐには使えないのでお手洗いのディスプレイとして少しの間飾らせていただいてます。','お世話になります。
店舗移店の為住所が変わりまして、
送っていただいた荷物の受取り、
アンケートの返信が遅くなり申し訳ございませんでした。
とてもご丁寧な対応をしていただき感動致しております。
同封して下さった石鹸をとても可愛くてすぐには使えないので
お手洗いのディスプレイとして少しの間飾らせていただいてます。
またＤＭを送る企画が出た際はお世話になると思いますので
どうぞ宜しくお願い致します。','5','/images/enquete/2012/364_huzz_f.jpg','/images/enquete/2012/364_huzz_dm.jpg'],['','/enquete/2012/','365','','ooz','食品メーカー','兵庫県','','','','4','/images/enquete/2012/365_ooz_f.jpg','/images/enquete/2012/365_ooz_dm.jpg'],['','/enquete/2012/','366','','dikk','住宅・建設関連会社','大阪府','','','','3','/images/enquete/2012/366_dikk_f.jpg','/images/enquete/2012/366_dikk_dm.jpg'],['2012/10/03','/enquete/2012/','367','255','tib','病院','千葉県','252','こちらの不手際にも丁寧に御対応頂き、最初から最後まで安心してお任せすることができました。','初めて利用させて頂きました。
こちらの不手際にも丁寧に御対応頂き、最初から最後まで安心してお任せすることができました。
また、メールやお電話での御対応もご親切にして頂き、感謝しております。
次回、機会がございましたら、利用させて頂きたいと思いました。','4','/images/enquete/2012/367_tib_f.jpg','/images/enquete/2012/367_tib_dm.jpg'],['','/enquete/2012/','368','','sakz','自動車関連会社','千葉県','','','','4','/images/enquete/2012/368_sakz_f.jpg','/images/enquete/2012/368_sakz_dm.jpg'],['2012/10/23','/enquete/2012/','369','256','nih','流通業','大阪府','1723','ともかく全てにおいて、利用者の立場に立った考え方が貫かれているように感じました。','今回依頼させていただいた印刷及びその発送は、
こちらとしても初めての試みであり不安もありました。
しかしながら、分からない点を質問すれば、
速やかに回答をいただけたことは、大変有り難かったです。
色々と詳細な資料を送っていただけたことも良かったです。
発注の流れについても、初めは戸惑いましたが、
分かり易く次に何をすれば良いかを提示していただけたおかげで
全体的にスムーズに進行出来たと思います。
ともかく全てにおいて、利用者の立場に立った考え方が
貫かれているように感じました。

そうした中で、気付いた点についても振れさせていただきたいと思います。
当初お送りいただいた「ＤＭ発送代行会社比較チェック表」についてですが、折角ここまで作られているのであれば
関数を用いて点数が自動計算される様にした方が、より良いのではと思います。
また、発送いただいた送付物の配達状況の確認についても、
指定フォーマットにてこちらで作成してお送りするエクセルファイルに
「問い合わせ番号」を付加してお送りいただけばより利便性が高まるのではと思います。
（検索ツールよりも上記のファイルを作る方が、はるかに簡単な気がします。）
また、発送件数が一定以上になると、
１件ずつ配達状況を問い合わせるのは非常に手間が掛かります。
今回はフリーソフトを用いて１００件ずつ確認することで
大幅に手間を削減しましたがそうした部分にまで気遣いされると、
更に満足度は高まるのではないかと思います。
以上、期待を込めての意見だと受け止めていただければと思います。','4','/images/enquete/2012/369_nih_f.jpg','/images/enquete/2012/369_nih_dm.jpg'],['2012/10/23','/enquete/2012/','370','257','min','システム関連会社','大阪府','858','ＤＭ送付から数日でお客様からのフィードバックがあったので、依頼して良ったと思いました。','電話とメールでのやり取りで不安に感じたが、ＤＭ送付から数日でお客様からの
フィードバックがあったので、依頼して良ったと思いました。
後、３社へ見積を依頼したのですが、一番対応も良く、安心することができました。','5','/images/enquete/2012/370_min_f.jpg','/images/enquete/2012/370_min_dm.jpg'],['2012/10/23','/enquete/2012/','371','258','tatp','製造販売業','東京都','1176','丁寧かつ、迅速なご対応のおかげで、トラブルもなく安心して、お願いすることができました。','初めての利用で、分からない事が多々ありましたが、
丁寧かつ、迅速なご対応のおかげで、トラブルもなく安心して、お願いすることができました。
次回も、利用させて頂きたいと思っています。
ありがとうございました。','5','/images/enquete/2012/371_tatp_f.jpg','/images/enquete/2012/371_tatp_dm.jpg'],['2012/10/25','/enquete/2012/','372','259','takh','行政書士事務所','北海道','740','都度、何度もハガキをいただき感心しました。（マネして参考としたいと思います）','・都度、何度もハガキをいただき感心しました。
（マネして参考としたいと思います）
・できれば、１枚でよいので完成品サンプルが欲しかった。','5','/images/enquete/2012/372_takh_f.jpg','/images/enquete/2012/372_takh_dm.jpg'],['2012/10/25','/enquete/2012/','373','260','mez','大学','東京都','1050','こちらの発送目標日を伝えておいたところ、原稿や宛名ラベルの到着日など、気にかけて下さり、ありがたかったです。','担当の犬飼様に大変丁寧で迅速な対応をして頂きました。担当としての
ごあいさつの葉書も頂き、連絡しやすかったです。こちらの発送目標日を伝えておいたところ
原稿や宛名ラベルの到着日など、気にかけて下さり、ありがたかった
です。仕上がった印刷物もきれいで、事前に見本で見ていた
通りの仕上がりで満足しています。今後も利用したいと考えています。
どうぞよろしくお願い申し上げます。
☆ありがとう石けんもありがとうございました。
御社の取り組む姿勢が伝わり、応援したい気持ちでいっぱいです。','5','/images/enquete/2012/373_mez_f.jpg','/images/enquete/2012/373_mez_dm.jpg'],['2012/10/26','/enquete/2012/','374','261','ryu','マーケティング関連','千葉県','980','当社ご担当者の不在時にも別の方からご連絡をいただき、組織的にも大変しっかりしていると信頼感が増しました。','・少量発送にも関わらず大変ていねいに対応していただき大変感謝しております。
・こちらの先走った振込みが原因であったのに、
　振込過多分につき貴社より返金を申告していただき、誠実な対応に感謝します。
・当社ご担当者の不在時にも別の方からご連絡をいただき、
　組織的にも大変しっかりしていると信頼感が増しました。
・失礼な言い方になりますが、大変信頼できる良い会社が見つかったと喜んでおります。
・今後とも機会がありましたらよろしくお願い致します。
　多謝　多謝！！！','5','/images/enquete/2012/374_ryu_f.jpg','/images/enquete/2012/374_ryu_dm.jpg'],['2012/10/30','/enquete/2012/','375','262','yumg','広告会社','愛知県','30921','作業をきっちりやっていただくことは当然として、その前後の対応がスピーディーでていねいでしたので、その点で安心しました。','作業をきっちりやっていただくことは当然として、その前後の対応が
スピーディーでていねいでしたので、その点で安心しました。
（見えない作業進行や品質チェックなどの部分が対応の良さで安心に変わりました）
持ちもどり数をカウントしていただけると良かったのですが…（多すぎましたね…）
石けんをありがとうございました！','4','/images/enquete/2012/375_yumg_f.jpg','/images/enquete/2012/375_yumg_dm.jpg'],['','/enquete/2012/','376','','murt','化学関連事業','大阪府','','','','4','/images/enquete/2012/376_murt_f.jpg','/images/enquete/2012/376_murt_dm.jpg'],['','/enquete/2012/','377','','simm','システム会社','東京都','','','','4','/images/enquete/2012/377_simm_f.jpg','/images/enquete/2012/377_simm_dm.jpg'],['2012/11/05','/enquete/2012/','378','263','enpw','WEBサービス事業','東京都','2114','お礼のハガキなど、とても丁寧な対応で安心しました。','お礼のハガキなど、とても丁寧な対応で安心しました。
