ありがとうございました。','4','/images/enquete/2012/378_enpw_f.jpg','/images/enquete/2012/378_enpw_dm.jpg'],['2012/11/07','/enquete/2012/','379','264','famr','司法書士事務所','愛知県','1000','本当に大丈夫か？という不信感がありました。そのことを伝えると、以前よりはメール連絡もあり、改善されたようでしたので安心しました。','問い合わせした内容、確認した内容についての
