多かったので、本当に大丈夫か？という不信感がありました。
そのことを伝えると、以前よりはメール連絡もあり、
改善されたようでしたので安心しました。
今後もよろしくお願い致します。','4','/images/enquete/2012/379_famr_f.jpg','/images/enquete/2012/379_famr_dm.jpg'],['','/enquete/2012/','380','','yazz','器機製造販売業','広島県','','','','4','/images/enquete/2012/380_yazz_f.jpg','/images/enquete/2012/380_yazz_dm.jpg'],['2012/11/09','/enquete/2012/','381','265','hard','酒店','岐阜県','8000','対応が終始ていねいであり、非常に信頼度が高いです','対応が終始ていねいであり、
非常に信頼度が高いです。
また利用したいと思います。','4','/images/enquete/2012/381_hard_f.jpg','/images/enquete/2012/381_hard_dm.jpg'],['','/enquete/2012/','382','','tmak','温泉施設','群馬県','','','','4','/images/enquete/2012/382_tmak_f.jpg','/images/enquete/2012/382_tmak_dm.jpg'],['','/enquete/2012/','383','','kydk','会計事務所','香川県','','','','4','/images/enquete/2012/383_kydk_f.jpg','/images/enquete/2012/383_kydk_dm.jpg'],['2012/11/21','/enquete/2012/','384','266','nism','出版社','東京都','1000','他のチラシ類であるものは先に受け入れをしていただいたので最後までスムーズに進行できました。','内容物が、ぎりぎりまで（こちらで用意する）印刷に時間がかかってしまいましたが
そのまま、他のチラシ類であるものは先に受け入れをしていただいたので
最後までスムーズに進行できました。
そろってから、手配していたら、いろいろ間にあわないところでした。
ありがとうございました。','4','/images/enquete/2012/384_nism_f.jpg','/images/enquete/2012/384_nism_dm.jpg'],['','/enquete/2012/','385','','onu','保険労務士事務所','埼玉県','','','','4','/images/enquete/2012/385_onu_f.jpg','/images/enquete/2012/385_onu_dm.jpg'],['2012/12/04','/enquete/2012/','386','269','ymt','不動産業','福岡県','512','愛知県と福岡県で遠方の会社より地元の会社をと最初は思っておりましたが、相見積の結果メディアボックスさんにご依頼することになり大正解でした。','愛知県と福岡県で遠方の会社より地元の会社をと最初は思っておりましたが、
相見積の結果メディアボックスさんにご依頼することになり大正解でした。
連絡もメール連絡があってから３時間以内という回答の速さ、処理の正確さにも満足致しましたし、ＤＭの仕上がりも満足しております。
プライバシーマークを取得されている安心感もあり、さすが検索エンジンで上位にきている会社さんだと思いました。
ＤＭ発送の機会がありましたら、また是非お願いしたいと思います。
ありがとうございました。','4','/images/enquete/2012/386_ymt_f.jpg','/images/enquete/2012/386_ymt_dm.jpg'],['2012/12/06','/enquete/2012/','387','270','hysy','飲食業','東京都','957','担当の方の電話、メールのサポートが非常に分かりやすく、安心な気持ちに変わっていきました。','ＤＭ（封書）の外注依頼は今回が初めてでした。しかも時間のない中で進めなければ
ならなかったので、不安でいっぱいでした。でも、担当の方の電話、メールのサポートが
非常に分かりやすく、安心な気持ちに変わっていきました。
また利用させて頂きます！ありがとうございました。
（すでに次の案件のやり取りを始めてますが・・・笑）','4','/images/enquete/2012/387_hysy_f.jpg','/images/enquete/2012/387_hysy_dm.jpg'],['2012/11/21','/enquete/2012/','388','267','uemi','商店','高知県','305','メールに字が多いのでわかりにくく感じます。それ以外はすばらしいと思います。','どう発注していいのかわかりずらかったです。
見積り～発注～作業完了までがもう少しわかりやすかったら、
メールに字が多いのでわかりにくく感じます。
それ以外はすばらしいと思います。','4','/images/enquete/2012/388_uemi_f.jpg','/images/enquete/2012/388_uemi_dm.jpg'],['','/enquete/2012/','389','','adw','セールスプロモーション事業','大阪府','','','','4','/images/enquete/2012/389_adw_f.jpg','/images/enquete/2012/389_adw_dm.jpg'],['2012/11/21','/enquete/2012/','390','268','sem','大学','千葉県','354','トータルでは非常に満足しています。','このたびは、ご対応いただきありがとうございました。
杉山様には短い期間ではありながらも、迅速に対応いただけたことで、
無事に書類を送付できました。
頻繁に連絡いただけたことで、確実に手続きを進められました。
ただ、ハガキは、あんなに送っていただかなくてもいいのでは？
と感じました。その分安くなるなど、価格やサービスに
転化いただきたく思いました。
ですが、トータルでは非常に満足しています。
ありがとうございました。','4','/images/enquete/2012/390_sem_f.jpg','/images/enquete/2012/390_sem_dm.jpg'],['2008/11/10','/enquete/2008/','391','51','aru','アパレル関連会社','神奈川県','1500','大変満足しております。今まで取引した全ての業界の会社の中でNo１です。','インターネットで検索し、価格が安かったので、ＨＰがわかりやすかったので問い合わせのTelをしました。
Telの対応が良かった為、こちらにお願いすることにしました。
作業途中でのメール対応も良く、全てにおいてきめ細かく親切で感じの良い対応でした。
