ホームページの分かりやすさと予算を下回る価格であることが
分かったため、さっそく見積り依頼をかけました。
他をあたろうとしていたところすぐレスポンスがあり、
担当いただいた門脇さんの電話・メールの対応もよかったため、
御社に決めさせていただきました。
納期、価格、仕上がりともに満足しています。
手書きのハガキには感動しました！','5','/images/enquete/2014/478_mor_f.jpg','/images/enquete/2014/478_mor_dm.jpg'],['2014/07/08','/enquete/2014/','479','328','her','メーカー','東京都','1063','問合せ、何らかの連絡の都度、確認のレスポンスが早く、案内も明確にわかりやすいので助かります。','（価格については、他で依頼していないので相対的には評価出来ない 為、ブランクです）
問合せ、何らかの連絡の都度、確認のレスポンスが早く、
案内も明確にわかりやすいので助かります。有難うございました。','4','/images/enquete/2014/479_her_f.jpg','/images/enquete/2014/479_her_dm.jpg'],['','/enquete/2014/','480','','sft','ソフト開発会社','東京都','','','','5','','/images/enquete/2014/480_sft_dm.jpg'],['','/enquete/2014/','481','','tya','税理士事務所','沖縄県','','','','4','','/images/enquete/2014/481_tya_dm.jpg'],['','/enquete/2014/','482','','sry','家具メーカー','東京都','','','','3','','/images/enquete/2014/482_sry_dm.jpg'],['','/enquete/2014/','483','','biy','美容関連会社','三重県','','','','4','','/images/enquete/2014/483_biy_dm.jpg'],['2014/08/27','/enquete/2014/','484','329','knk','会計事務所','東京都','1260','初めて利用させて頂きましたが、全てにおいて丁寧にご対応頂きありがとうございました。','初めて利用させて頂きましたが、全てにおいて丁寧に
ご対応頂きありがとうございました。
原稿の訂正・差し替え、発送日の件では、
大変お手数をお掛けしましたが無事に完了いたしました。
事後整理に時間がかかり、お送りするのが今頃になってしまいました。
次回もお願いしたいと思っておりますので、よろしくお願い致します。','5','/images/enquete/2014/484_knk_f.jpg','/images/enquete/2014/484_knk_dm.jpg'],['2014/09/04','/enquete/2014/','485','330','zyei','医療関連事業','大阪府','200','これほど丁寧で、サービスがいき届いて、なおかつ安くて安心ができる無敵だなと思いました。また必ず依頼させていただきます。','今回ははじめて御社に依頼しました。値段が大変安く、かつ信頼度
