理由がわかりました。都度メールで迅速なご対応をいただき
直筆のおハガキまでいただいたのは初めてです。
これほど丁寧で、サービスがいき届いて、なおかつ安くて安心ができる
無敵だなと思いました。
また必ず依頼させていただきます。ありがとうございました。','5','/images/enquete/2014/485_zyei_f.jpg','/images/enquete/2014/485_zyei_dm.jpg'],['','/enquete/2014/','486','','mrs','メーカー','福井県','','','','4','','/images/enquete/2014/486_mrs_dm.jpg'],['2014/09/04','/enquete/2014/','487','331','rogn','IT関連事業','東京都','639','お問合わせへの対応が迅速、且つ丁寧な点が好印象でした','お問合わせへの対応が迅速、且つ丁寧な点が好印象でした。
ご送付頂きました資料は、ややボリュームが多く、
せっかく頂きながら目が通せておりません。
申し訳ありません。
お手紙も何度か頂きましたが、ご注文させて頂いた内容
（枚数等）を考えると恐縮してしまいました。
次回ご依頼の際は、"手抜き"をして頂いて構いません。
最後になりますが、"オリジナル石鹸"ありがとうございます。
お気遣いに心より感謝申し上げます。
追伸：8/3　ＤＭよりお問合せのTELがありました！','4','/images/enquete/2014/487_rogn_f.jpg','/images/enquete/2014/487_rogn_dm.jpg'],['2014/09/08','/enquete/2014/','488','332','cazb','ペット用品卸業','北海道','440','この度初めてお願いしましたが、メールだけのやりとりで少々不安もありましたが、お礼のハガキなど頂いておりましたので安心出来ました。','お世話になりました。
この度初めてお願いしましたが、
