対応をしてくださり、私はとても気楽に相談することが
できました。今後、DMを送る機会がありましたら
ぜひまた御社にお願いしたいと考えております。','0','/images/enquete/2015/000_mdsep_f.jpg',''],['2015/07/14','/enquete/2015/','565','394','nnb','貿易会社','神奈川県','1397','価格の安さにも満足し、作業の軽減もできて、大いに助かりました。','初めて発注したが、適切な対応で、作業についても
