価格、安さに感謝です。','4','/images/enquete/2015/566_ikt_f.jpg','/images/enquete/2015/566_ikt_dm.jpg'],['2015/08/03','/enquete/2015/','567','396','rtn','旅行会社','東京都','599','600部という中途半端な部数にも心良く対応頂き感謝しております。','今回の、初のDMで不慣れな点が多かったのですが、早急に
