心良く対応頂き感謝しております。
また、事あるごとに手書きのおはがきを送り頂き
同じサービス業として勉強になりました。
今後共利用させて頂きたいと思います。','5','/images/enquete/2015/567_rtn_f.jpg','/images/enquete/2015/567_rtn_dm.jpg'],['2015/08/05','/enquete/2015/','568','397','hip','人材関連事業','東京都','300','価格が安いのに対応の早さ丁寧さに驚きました。','価格が安いのに対応の早さ丁寧さに驚きました。
