ありがとうございました。','5','/images/enquete/2015/568_hip_f.jpg','/images/enquete/2015/568_hip_dm.jpg'],['2015/08/13','/enquete/2015/','569','398','syu','印刷業','東京都','5417','電話での対応や度重なる見積りにも迅速に対応していただき、助かりました。','今の度は大変お世話になりました。
