満足しています。','この度はおせわになりました。
発送までの手順が分かりやすくメール、
ＴＥＬでのやりとりで済むので
よかったです。
早速お客様からのお問い合わせをいただくことができ
満足しています。
今後ともよろしくお願いします。','4','/images/enquete/2015/574_knt_f.jpg','/images/enquete/2015/574_knt_dm.jpg'],['2015/10/06','/enquete/2015/','575','401','ink','システム開発','東京都','500','レスポンスの速さと、依頼内容に細かく対応してくれるかが気になり、複数社見積りを取った中で、選定しました。','初回の依頼だった為、レスポンスの速さと、依頼内容に細かく対応
してくれるかが気になり、複数社見積りを取った中で、選定しました。
宛名データ、印刷データ、封入物の送付先が分かりやすいと
もっと良かったです。
封入物をバラバラにメールや宅急便で送るので、どの注文の封入物か
分からなくならないかが、少々不安でした。','4','/images/enquete/2015/575_ink_f.jpg','/images/enquete/2015/575_ink_dm.jpg'],['2015/10/08','/enquete/2015/','576','402','tikj','住宅関連会社','愛知県','371','遂一メールを頂くことができ安心して利用できました。','この度は迅速かつ、丁寧にご対応頂き、誠にありがとうございました。
初めてのことでしたので、少し心配でしたが遂一メールを頂くことができ
安心して利用できました。
また機会がありましたらよろしくお願い致します。','4','/images/enquete/2015/576_tikj_f.jpg','/images/enquete/2015/576_tikj_dm.jpg'],['2015/10/15','/enquete/2015/','577','403','frp','医療機器関連','埼玉県','734','おかげさまで、少しずつ反響が出て参りました。','始めてだったので、こちらが慣れておらず、不手際が多くご迷惑をおかけしましたが
無事発送頂き、ありがとうございました。
おかげさまで、少しずつ反響が出て参りました。
次回は、いつまた実施できるか分かりませんが、その時も宜しくお願い致します。','4','/images/enquete/2015/577_frp_f.jpg','/images/enquete/2015/577_frp_dm.jpg'],['2015/10/15','/enquete/2015/','578','404','nmbr','治療院','東京都','541','これほど気持ちよく、ノンストレスで仕事ができたのは、初めての経験かもしれません。','今回、初めて利用させて頂きました。年4回、ニュースレターを発刊して
いますが、発送における労力、かかる時間が非常に負担となっており、
「良い外注先はないものか？」とネットでメディアボックスさんを知りました。
一通りの発送業務のやり取りをさせて頂き、お願いして、大正解だったと、
とても満足しています。
具体的には、丁寧なメール対応、資料として送付して頂いた「ご利用者さんの声」
契約前後のお手紙、随時のホウレンソウの徹底。最後には「ありがとう石けん」のプレゼントまで。
全てのプロセスに関心させられました。
これほど気持ちよく、ノンストレスで仕事ができたのは、初めての経験かもしれません。
また、ＭＤさんの仕事やファン化の仕組みは大変素晴らしく、
当方の治療院経営に生かせる点ばかりで、大変勉強になりました。
今後も永いお付き合いを宜しくお願い申し上げます。
この度は誠にありがとうございます。','5','/images/enquete/2015/578_nmbr_f.jpg','/images/enquete/2015/578_nmbr_dm.jpg'],['2015/10/19','/enquete/2015/','579','405','hny','出版社','東京都','505','最後まで心のこもった対応が印象的でした。','初めて利用させていただいたのですが
一番初めの見積りの段階から丁寧にご対応いただき
大変感謝しております。
メールはもちろんの事、手書きのハガキを送っていただいたりと
最後まで心のこもった対応が印象的でした。
私自身、初めてのＤＭ発送でしたので、右も左も分からず
たくさん質問しましたが、無事発送できたのも
御社のおかげです。またありましたら、よろしくお願いいたします。','5','/images/enquete/2015/579_hny_f.jpg','/images/enquete/2015/579_hny_dm.jpg'],['','/enquete/2015/','580','','fza','人材サービス業','大阪府','','','','5','','/images/enquete/2015/580_fza_dm.jpg'],['','/enquete/2015/','581','','tok','大学','東京都','','','','4','','/images/enquete/2015/581_tok_dm.jpg'],['2015/10/26','/enquete/2015/','582','406','mtu','運送会社','東京都','129','顔が見えない取引であるからこそ、このような良さを余計に感じるのかもしれませんが、貴社にお願いして良かったと思っております。','この度は大変お世話になりました。
初めてのＤＭ発送ということもあり、普段の業務と並行して自分達で作業する
のか、業社に委託するのかをコスト試算するところから始めました。
貴社につきましては、最初にいただいた見積もりや資料の丁寧さはもとより、
ご担当者様の対応の良さや気遣いなど価格以上の魅力を感じました。
顔が見えない取引であるからこそ、このような良さを余計に感じるのかもしれ
ませんが、貴社にお願いして良かったと思っております。
また是非お願いしたいと思っておりますので、次回も宜しくお願い申し上げます。','4','/images/enquete/2015/582_mtu_f.jpg','/images/enquete/2015/582_mtu_dm.jpg'],['2015/10/30','/enquete/2015/','583','407','mdr','医薬品関連','神奈川県','1603','いつもメールやハガキでのご連絡がとてもうれしく、私自身そのような対応をぜひまねしたいと思えました。','初回のお見積りのご連絡からお返事や対応がとても早く、そして
丁寧・親切なやりとりを心がけていらっしゃるのがとても伝わってきました。
いつもメールやハガキでのご連絡がとてもうれしく、私自身そのような対応を
ぜひまねしたいと思えました。
これから毎月、郵送業務が入るので、またメディアボックスさんに依頼させて頂きます。
ありがとうございました。','5','/images/enquete/2015/583_mdr_f.jpg','/images/enquete/2015/583_mdr_dm.jpg'],['','/enquete/2015/','584','','cdt','保険会社','愛知県','','','','4','','/images/enquete/2015/584_cdt_dm.jpg'],['','/enquete/2015/','585','','tkk','大学','東京都','','','','5','','/images/enquete/2015/585_tkk_dm.jpg'],['2015/11/26','/enquete/2015/','586','408','enkk','不動産業','山梨県','28224','仕様の変更等結構無理をお願いしましたが快く受けて頂きとても助かりました。','メール中心の対応としては非常にきめ細かい対応でした。
