宜しくお願い致します。','5','/images/enquete/2015/587_espt_f.jpg','/images/enquete/2015/587_espt_dm.jpg'],['','/enquete/2015/','588','','ikya','飲食店','滋賀県','','','','3','','/images/enquete/2015/588_ikya_dm.jpg'],['','/enquete/2015/','589','','eikk','スポーツ関連','東京都','','','','4','','/images/enquete/2015/589_eikk_dm.jpg'],['2015/12/17','/enquete/2015/','590','410','nag','印刷業','東京都','500','人手不足と効率の悪さに困っておりました。大変助かりました。','大変お世話になりました。
