大変助かりました。今後ともよろしくお願い申し上げます。','4','/images/enquete/2015/590_nag_f.jpg','/images/enquete/2015/590_nag_dm.jpg'],['2015/12/21','/enquete/2015/','591','413','grdp','アパレル関連','東京都','543','こまやかなメールでの対応でスムーズに進めることができました。','初めて代行発送を利用したため、手順等
わからないことが多かったのですが
こまやかなメールでの対応でスムーズに
