お葉書もいただき本当に嬉しかったですが、御社の利益はあるのかな？と心配になります。
これまで１人で他の仕事のあい間にコツコツ進めていたＤＭを代行して頂けて、しかも自分で発送するより
低コスト。本当に感謝です。次回も必ず依頼させて頂きますね。ありがとうございました。
1つだけ希望としては、お支払いがもう少し時間が取れたら、完璧です。','5','/images/enquete/2015/592_fncj_f.jpg','/images/enquete/2015/592_fncj_dm.jpg'],['2015/12/22','/enquete/2015/','593','414','kkt','劇団','東京都','1723','最終的にもお客様に正確にＤＭを届けることができました。返戻分の対応も、まとめやすく大変ありがたかったです。','初めて利用させて頂きました。個人情報を取り扱う上で、代行会社に
