(ヤマトメール便廃止にて、チラシをそのまま郵便で送るのは相当予算がかさむため)
心配なこちらの心中を察して下さるかのように、電話での対応も丁寧で
メールでの問合せにもすぐにご対応して下さいました。おかげで安心して
お任せする状況に至り、最終的にもお客様に正確にDMを届けることができました。
また、返戻分の対応も、まとめやすく大変ありがたかったです。
また利用させて頂きます。今後ともよろしくお願い致します。','5','/images/enquete/2015/593_kkt_f.jpg','/images/enquete/2015/593_kkt_dm.jpg'],['2015/12/17','/enquete/2015/','594','412','yhb','飲食店','愛知県','1219','丁寧に対応していただき、ストレスも無く大変、満足しております。コスト面でも、満足です。','お世話になっております。
