小口の依頼でしたが、個人で事業を行っている手前、作業時間を別の仕事に
充てたいと思っていたところ、御社に出会え、良かったです。
「ありがとう石けん」ありがとうございます。
身内に身障者がいて、同じように施設でモノを作っているので嬉しくなりました。
今後ともどうぞ宜しくお願い致します。','5','/images/enquete/2016/599_ansf_f.jpg','/images/enquete/2016/599_ansf_dm.jpg'],['2016/01/26','/enquete/2016/','600','417','zefz','印刷関連','東京都','7334','途中のやりとりも随時メール等でお知らせをいただく事で実際の距離感を感じさせない仕事をしていただいたと思う。','今回初めてＤＭを発注させていただいたが、
