次回発送時にもお声がけいたします。よろしくお願いします。
ご対応いただきました出口様にもよろしくお伝えください。
ありがとうございました。','4','/images/enquete/2016/652_dirk_f.jpg','/images/enquete/2016/652_dirk_dm.jpg'],['','/enquete/2016/','653','','ossj','歯科関連','広島県','','','','4','','/images/enquete/2016/653_ossj_dm.jpg'],['2016/10/05','/enquete/2016/','654','450','tck','税理士事務所','東京都','175','確認する資料が多かったため、初回は少々分かりにくかった。それ以外は全て良かったです。','メールと添付ファイルと、確認する資料が多かったため、
初回は少々分かりにくかった。
1つのファイルにフローの形で、データ作成から支払い、
