それ以外は全て良かったです。','5','/images/enquete/2016/654_tck_f.jpg','/images/enquete/2016/654_tck_dm.jpg'],['2016/10/06','/enquete/2016/','655','451','hnk','物流関連','千葉県','145','発送する資料についてもコストが安くなるようなご提案を頂き有難うございました。','ＤＭの発送代行を依頼するのは初めてでしたが
