有難うございました。','4','/images/enquete/2016/655_hnk_f.jpg','/images/enquete/2016/655_hnk_dm.jpg'],['','/enquete/2016/','656','','nsae','広告業','福井県','','','','4','','/images/enquete/2016/656_nsae_dm.jpg'],['','/enquete/2016/','657','','ore','機器製造販売業','東京都','','','','5','','/images/enquete/2016/657_ore_dm.jpg'],['','/enquete/2016/','658','','kms','システム開発会社','大阪府','','','','4','','/images/enquete/2016/658_kms_dm.jpg'],['2016/10/19','/enquete/2016/','659','452','alb','システム開発会社','愛知県','442','手紙のDMには、感動しましたよ！手間のかかることこそ大切にされているのですね！','御社の体制の一貫ではあると思いますが
お電話に出ていただいた方（門脇唯様）がそのまま担当となり
とてもスムーズでした。
その中で「手紙のＤＭ」には、感動しましたよ！
とても嬉しかったです。手間のかかることこそ大切にされているのですね！
大切なことです。ありがとうございました。','5','/images/enquete/2016/659_alb_f.jpg','/images/enquete/2016/659_alb_dm.jpg'],['2016/10/27','/enquete/2016/','660','453','hsk','コンサルティング会社','京都府','3015','宛名ラベルデータの急な差し換えで大変ご迷惑をおかけしましたが、担当の門脇様にご配慮頂き大変助かりました。','宛名ラベルデータの急な差し換えで大変ご迷惑を
おかけしましたが、担当の門脇様にご配慮頂き
大変助かりました。次回以降もDM発送の際には
是非宜しくお願い申し上げます。','5','/images/enquete/2016/660_hsk_f.jpg','/images/enquete/2016/660_hsk_dm.jpg'],['2016/10/28','/enquete/2016/','661','454','knk','リフォーム会社','千葉県','1725','出来上がりのサンプルを見たかったです。それ以外は満足です。','１つだけ不満が…
出来上がりのサンプルを見たかったです。
どの様な形でお客様の所にＤＭが行くか不安
だったので１通だけでも会社に同じ物を送って
頂くか、作成前にメールでも良いので見せて
頂きたかったです。それ以外は満足です。','4','/images/enquete/2016/661_knk_f.jpg','/images/enquete/2016/661_knk_dm.jpg'],['2016/10/28','/enquete/2016/','662','455','mdm','出版社','東京都','105','小口でも受けてもらえて感謝です。手順がすごくていねいですね。','小口でも受けてもらえて感謝です。
発送まで予想以上に日数がかかったのが予定外でした。
1日早くして頂いてありがとうございました。
手順がすごくていねいですね。
PDFで送ったものについての書体の確認はやはり必要でしょうか？
「ありがとう石けん」ありがとうございました。
作業風景の写真もいいですね。','5','/images/enquete/2016/662_mdm_f.jpg','/images/enquete/2016/662_mdm_dm.jpg'],['','/enquete/2016/','663','','ysd','デザイン事務所','東京都','','','','4','','/images/enquete/2016/663_ysd_dm.jpg'],['2016/10/28','/enquete/2016/','664','456','koy','リフォーム会社','島根県','245','都度丁寧に話をきいて下さったりメールして下さったりとても分かり易く良かったです。','発送代行してくれる会社自体知らなくて、最初はとてもとまどいました。
