こちらが分かりにくい説明をしても、分かっていただいたので
ありがたかったです。
これからもよろしくお願いします。','4','/images/enquete/2016/666_koyi_f.jpg','/images/enquete/2016/666_koyi_dm.jpg'],['','/enquete/2016/','667','','mth','Web制作会社','東京都','','','','4','','/images/enquete/2016/667_mth_dm.jpg'],['2016/11/07','/enquete/2016/','668','458','etc','清掃業','大阪府','371','手書きのハガキをいただいたり、お礼の挨拶とプレゼントには感激しました。','メールのみのやりとりでしたが、ていねいで分かりやすく対応
していただきました。
手書きのハガキをいただいたり、お礼の挨拶とプレゼント
には感激しました。ありがとうございました。
勉強になります。次回はＤＭの内容を変えてみたいと思います。
今後もよろしくお願いします。','5','/images/enquete/2016/668_etc_f.jpg','/images/enquete/2016/668_etc_dm.jpg'],['2016/11/12','/enquete/2016/','669','459','yet','建築関連会社','埼玉県','1158','その都度、担当して下さった門脇さんが親切な対応をして下さり安心して、注文する事が出来ました。','今回は、ありがとうございました。
ＤＭ作成等を行うのが初めてだったので、何をどうしたらよいのか
わからない事も多かったのですが
その都度、担当して下さった門脇さんが親切な対応をして下さり
安心して、注文する事が出来ました。
毎回、アクションが1つ終わる毎にメールやお葉書を頂けたのも
とても、あたたかい気持ちになりました。
次回も、またよろしくお願い致します。','4','/images/enquete/2016/669_yet_f.jpg','/images/enquete/2016/669_yet_dm.jpg'],['','/enquete/2016/','670','','dirk','技術関連','東京都','','','','4','','/images/enquete/2016/670_dirk_dm.jpg'],['','/enquete/2016/','671','','zhns','財団法人','東京都','','','','5','','/images/enquete/2016/671_zhns_dm.jpg'],['2016/11/12','/enquete/2016/','672','460','dsh','医療関連','東京都','345','都度おハガキも送ってくださったり、最後は石けんまで。。。感謝ばかりです。','何度連絡しても、いつも丁寧にご対応いただきました。
都度おハガキも送ってくださったり、最後は石けんまで。。。
感謝ばかりです。
1つあれば、支払いが前払いのみなのが。。。もう少し幅があると助かります。
またお世話になると思いますので、その際はよろしくお願い致します。','5','/images/enquete/2016/672_dsh_f.jpg','/images/enquete/2016/672_dsh_dm.jpg'],['2016/11/24','/enquete/2016/','673','461','kks','機器メーカー','東京都','1500','印刷サンプルは、DM発送と同時にいただきたい。','・お支払いが、短期間なので社内的に経理に負担になっている。
　通常の締日、支払い日の支払い条件で取引きさせてほしい。
・印刷サンプルは、ＤＭ発送と同時にいただきたい。','3','/images/enquete/2016/673_kks_f.jpg','/images/enquete/2016/673_kks_dm.jpg'],['2016/11/29','/enquete/2016/','674','462','stq','スタジオ事業','東京都','7017','何より、細やかなおハガキやカタログなどとても嬉しく思いました。','今回は、初めてでしたのでスムーズに進行するか心配でしたが
細いご配慮のメールや、システムで問題なく発送することが
できました。私は、クライアント様にスケジュールを伝えるのに、
カレンダー表にして図解しています。一目でスケジュールが解かる様な
表組み（エクセル）で確認できると、一目で情報が共有できると思いました。
何より、細やかなおハガキやカタログなどとても嬉しく思いました。
Netで依頼する仕事が多い中、顔が見えない分、この様な心使いは
とても良い事だと思いました。
今後も、宜しくお願い致します。','5','/images/enquete/2016/674_stq_f.jpg','/images/enquete/2016/674_stq_dm.jpg'],['2016/12/05','/enquete/2016/','675','463','kks','環境関連事業','東京都','95','小口発送可の点も良でした。','初めての依頼で、やりとりに不安もありましたが
