今後とも、よろしくお願い致します。','5','/images/enquete/2016/676_hhmn_f.jpg','/images/enquete/2016/676_hhmn_dm.jpg'],['2016/12/08','/enquete/2016/','677','465','kkks','医療機関','大阪府','2182','値段を安くされる理由として、入金後の発送は理解できます。','入金後のＤＭ発送ルールは、理解できておらず、
電話で行き違いが発生した。
締め支払い日が決まっているため、社内での調整が大変だった。
値段を安くされる理由として、入金後の発送は理解できます。','4','/images/enquete/2016/677_kkks_f.jpg','/images/enquete/2016/677_kkks_dm.jpg'],['2016/12/10','/enquete/2016/','678','466','ezcm','コンサルティング会社','東京都','1000','大変良い仕上がりで印刷のクオリティにも満足しています。','印刷もお願いして発送して頂いたので、仕上がりを見ていなかったのですが
関連会社を宛先に入れて届いたのを見ることができました。
大変良い仕上がりで印刷のクオリティにも満足しています。
担当された出口さんには大変お世話になりました。
ＤＭの発送は初めての経験でしたが、大変スムーズに行うことができ
感謝いたしております。
千三つといわれるＤＭの世界ですが、8日に発送されて9日朝10時に
しかも遠方の山口県から申し込みを頂くという極めていいスタートをきる
ことができました。すべて御社のお陰と存じます。
今後ともよろしくお願いいたします。
ＰＳ.ありがとう石鹸　大切に使わせて頂きます。','5','/images/enquete/2016/678_ezcm_f.jpg','/images/enquete/2016/678_ezcm_dm.jpg'],['2016/12/12','/enquete/2016/','679','467','skid','製造メーカー','大阪府','328','不足があった場合でも丁寧に対応して頂き
　安心して、お願いすることができました。','不足があった場合（当社渡す内容に）でも丁寧に対応して頂き
安心して、お願いすることができました。
ありがとうございます。','5','/images/enquete/2016/679_skid_f.jpg','/images/enquete/2016/679_skid_dm.jpg'],['2016/12/12','/enquete/2016/','680','468','ass','システム開発','東京都','130','貴社全体から"温かみを感じる対応"がありとても満足しております。','知人の紹介で貴社を知り、利用させて頂きました。
