安心してお任せすることができました。
また貴社全体から"温かみを感じる対応"があり
とても満足しております。
又利用させて頂きたいと思いますので
今後ともよろしくお願い致します。
この度はありがとうございました！
追伸 "ありがとうせっけん"ありがとうございました！','5','/images/enquete/2016/680_ass_f.jpg','/images/enquete/2016/680_ass_dm.jpg'],['2016/12/13','/enquete/2016/','681','469','raeb','Web制作会社','東京都','636','他社にも見積りを依頼しましたが、一番丁寧な対応で価格もどこよりも安く、こまめに連絡をいただけました。','他社にも見積りを依頼しましたが、一番丁寧に対応していただきました。
価格もどこよりも安く、こまめに連絡をいただけ安心しておまかせすること
