できました。次回もお願いしたいです。
ありがとうございました。','5','/images/enquete/2017/687_shnr_f.jpg','/images/enquete/2017/687_shnr_dm.jpg'],['','/enquete/2017/','688','','ydg','製造業','岐阜県','','','','5','','/images/enquete/2017/688_ydg_dm.jpg'],['','/enquete/2017/','689','','ybz','機器販売業','富山県','','','','5','','/images/enquete/2017/689_ybz_dm.jpg'],['2017/01/27','/enquete/2017/','690','475','arm','技術関連事業','東京都','259','少額の依頼でしたが、担当者様の対応はとても良かったです。','期間/価格は他社比較していないのでわかりませんが、
自社でDM発送するよりトータルコストは安い様に感じております。
少額の依頼でしたが、担当者様の対応はとても
良かったです。当社も見習いたいです。
今後ともよろしくお願い致します。','5','/images/enquete/2017/690_arm_f.jpg','/images/enquete/2017/690_arm_dm.jpg'],['2017/02/06','/enquete/2017/','691','476','rgl','ホテル','大阪府','503','低価格なのに、非常に丁寧な対応でとても安心致しました。','低価格なのに、非常に丁寧な対応でとても安心致しました。（ご担当：門脇様）
次回ＤＭ発送はいつになるかわかりませんが、
次もぜひ利用させて頂きたいです。
ありがとうございました。','5','/images/enquete/2017/691_rgl_f.jpg','/images/enquete/2017/691_rgl_dm.jpg'],['2017/02/07','/enquete/2017/','692','477','dts','図書関連事業','東京都','1117','驚きの速さと価格で発送して頂き感謝しています。','この度はありがとうございました！
今までは自分たちかなりの時間をかけて発送をしていましたが
驚きの速さと価格で発送して頂き感謝しています。
また近々利用する予定ですので、
今後とも宜しくお願い致します。','5','/images/enquete/2017/692_dts_f.jpg','/images/enquete/2017/692_dts_dm.jpg'],['2017/02/09','/enquete/2017/','693','478','atms','システム開発','神奈川県','300','担当の方が付いてくださるのは、とても心強かったです。','この度は、DM発送の対応をして頂き
誠にありがとうございました。
私は新入社員なものでして、初めてのDM発送に
少々不安を感じていたのですが
メールからお電話まで、全てにおいて
分かりやすいご説明があった為、安心しました。
担当の方が付いてくださるのは、とても心強かったです。
また、途中私が体調を崩してしまい、ご迷惑をお掛けしました。
次回貴社に依頼させて頂く際は、しっかりと体調を整え
最後まで対応致します。
改めまして、丁寧な対応をして頂き、ありがとうございました。
今後とも宜しくお願い致します。','5','/images/enquete/2017/693_atms_f.jpg','/images/enquete/2017/693_atms_dm.jpg'],['2017/02/10','/enquete/2017/','694','479','hmsk','歯科医院','大阪府','783','出来上がりも綺麗でスタッフ一同喜んでおります。','お世話になるのは初めてでしたので、
やり取りに少々手間取りましたが
丁寧に対応してくださり、安心いたしました。
最後まで見積もり内容の変更など、ご迷惑をおかけしましたが
お電話で早急に対処してくださり、ありがとうございます。
出来上がりも綺麗でスタッフ一同喜んでおります。
今後も宜しくお願い致します。','5','/images/enquete/2017/694_hmsk_f.jpg','/images/enquete/2017/694_hmsk_dm.jpg'],['2017/02/14','/enquete/2017/','695','480','iwk','石材関連事業','奈良県','1197','ネット通販は顔が見えない、という不安を解消する会社の取り組みが素晴らしいです。','丁寧な対応と細やかな配慮が良かったです。「ネット通販は顔が見えない」
という不安を解消する会社の取り組みが素晴らしいです。
自社のマーケティングにも生かしたいと思います。
1つ難点をあげるとすれば、ＤＭ宛名不明で返却されるものが多いです。
すべてゆうメールにて再配達完了しました。（住所変更されたものは1～2件あると思われます）
ただし、これはヤマトの問題かもしれません。
メディアボックスさんの品質を保持するために、指導された方が良いと思います。','5','/images/enquete/2017/695_iwk_f.jpg','/images/enquete/2017/695_iwk_dm.jpg'],['2017/02/21','/enquete/2017/','696','481','hmr','住宅関連事業','愛知県','670','また作業過程にかんする細かいご連絡も頂けたので心より安堵しております。','この度は、ありがとうございました。
最初はどのようにしてよいのかわからず、困惑しておりましたが
その都度担当の方が詳しくそして丁寧にお教えして頂き安心することができました。
また作業過程にかんする細かいご連絡も頂けたので
心より安堵しております。
メールや電話だけでなく、お葉書きまで頂き
とてもよいお取引きができたと感謝しております。
また次回も何卒よろしくお願い申し上げます。','5','/images/enquete/2017/696_hmr_f.jpg','/images/enquete/2017/696_hmr_dm.jpg'],['2017/03/05','/enquete/2017/','697','482','ird','デザイン事務所','大阪府','301','メールでの質問もすぐにお返事下さいました。','色々調べる中で御社のＨＰを見ました。
