わかりやすく、そしてご対応頂けて本当に助かりました。
メールでの質問もすぐにお返事下さいました。
次回もまたお願いしたいと思います。
今後共、どうぞ宜しくお願い致します。','5','/images/enquete/2017/697_ird_f.jpg','/images/enquete/2017/697_ird_dm.jpg'],['2017/03/06','/enquete/2017/','698','483','kgdg','大学','群馬県','1130','価格だけでなく、対応にも大満足です。','メールだけでの対応でしたが、返信が早く、
安心してお取引することができました。
初めての利用だったので、わからないことも多く、
度々質問させていただきましたが
全てに丁寧に対応していただけました。
価格だけでなく、対応にも大満足です。
機会があったら、また利用させていただきたいです。','4','/images/enquete/2017/698_kgdg_f.jpg','/images/enquete/2017/698_kgdg_dm.jpg'],['2017/03/10','/enquete/2017/','699','484','bbos','システム開発','東京都','1081','セミナーの申込率を確認し、次回の依頼をさせて頂きたく考えています。','丁寧な対応誠にありがとうございました。
