大変嬉しく感じました。
また次回お願いしたいと思っております。','5','/images/enquete/2017/707_hrm_f.jpg','/images/enquete/2017/707_hrm_dm.jpg'],['','/enquete/2017/','708','','rtc','木材関連事業','静岡県','','','','4','','/images/enquete/2017/708_rtc_dm.jpg'],['2017/04/20','/enquete/2017/','709','492','gnsz','飲食業','和歌山県','531','作業完了の度にメールがきたり、発送日等も明確なところが良かったです。','今回、初めて利用させていただいたのですが、電話もメールも
