下さったり、こうして石けんをいただいたり、メールのレスポンス
が早かったりと、さすがＤＭのプロの方でいらっしゃるなと
びっくりしました。
ありがとうございました。','5','/images/enquete/2017/715_krk_f.jpg','/images/enquete/2017/715_krk_dm.jpg'],['2017/05/25','/enquete/2017/','716','495','ccb','リフォーム会社','大阪府','380','お送りいただいた資料やＨＰの評判通り、流れが分かりやすくスタッフの方々の対応が誠実で良かったです。','お送りいただいた資料やＨＰの評判通り、流れが分かりやすく
