早速お送り頂いたＤＭから反響もあり、迅速な対応のおかげと
感謝いたします。
また、ありがとう石鹸もすばらしいですね。作って下さった方々にも
美しい石鹸をありがとう！とお伝え頂けましたら幸いです。
今後とも宜しくお願い申し上げます。','5','/images/enquete/2017/721_wm_f.jpg','/images/enquete/2017/721_wm_dm.jpg'],['2017/06/14','/enquete/2017/','722','500','wtr','コンサルティング事業','東京都','500','また依頼させていただきますので宜しくお願い致します。','お世話になります。今回はありがとうございました。
また依頼させていただきますので宜しくお願い致します。
それからエクセルでお送りしました個人情報は厳重な処理を
いただけますようお願いいたします。','5','/images/enquete/2017/722_wtr_f.jpg','/images/enquete/2017/722_wtr_dm.jpg'],['','/enquete/2017/','723','','bce','セキュリティー関連','東京都','','','','4','','/images/enquete/2017/723_bce_dm.jpg'],['','/enquete/2017/','724','','ebr','スポーツ関連事業','東京都','','','','5','','/images/enquete/2017/724_ebr_dm.jpg'],['2017/06/29','/enquete/2017/','725','501','evp','デザイン会社','兵庫県','27643','メール、電話での対応がすばらしかったので、段々と不安はなくなりました。','初めての利用でしたので、若干不安なところはありましたが
