不安はなくなりました。
結果的に御社にお願いして良かったと思っています。
次回も必ずお願いします。','5','/images/enquete/2017/725_evp_f.jpg','/images/enquete/2017/725_evp_dm.jpg'],['','/enquete/2017/','726','','nzk','機械販売','福井県','','','','5','','/images/enquete/2017/726_nzk_dm.jpg'],['','/enquete/2017/','727','','rtb','メディカル関連事業','神奈川県','','','','5','','/images/enquete/2017/727_rtb_dm.jpg'],['2017/07/11','/enquete/2017/','728','502','sys','システム開発','東京都','2001','業界をよくしたい、という姿勢に感銘しております。','ご料金の設定に満足しております。
但、事故防止、作業定型化の観点からと存じますが
メールが長文かつ頻度が多く、弊社で時間を
取れない中でのオペレーションについては、再確認
をしたいと社内では考えております。
業界をよくしたい、という姿勢に感銘しております。','3','/images/enquete/2017/728_sys_f.jpg','/images/enquete/2017/728_sys_dm.jpg'],['2017/07/25','/enquete/2017/','729','503','inm','機器メーカー','東京都','1110','依頼するとした決め手は、メール対応が迅速・丁寧であること、価格がとてもリーズナブルであること、また、事前情報が豊富であったことです。','印刷から発送まで、代行していただけるとの事で、
メディアボックス様に依頼をしました。
依頼するとした決め手は、メール対応が迅速・丁寧であること
価格がとてもリーズナブルであること、また、事前情報が
豊富であったこと（資料を送って頂いたこと）です。
とても満足でした!!　ありがとうございました!!','4','/images/enquete/2017/729_inm_f.jpg','/images/enquete/2017/729_inm_dm.jpg'],['','/enquete/2017/','730','','rbd','不動産会社','埼玉県','','','','4','','/images/enquete/2017/730_rbd_dm.jpg'],['','/enquete/2017/','731','','krc','音楽関連事業','愛知県','','','','4','','/images/enquete/2017/731_krc_dm.jpg'],['','/enquete/2017/','732','','svs','商社','東京都','','','','5','','/images/enquete/2017/732_svs_dm.jpg'],['2017/09/01','/enquete/2017/','733','504','cmp','コンサルタント会社','東京都','1000','発送後のご連絡もいただき、フォローもしっかりしている企業様だと感じました。','電話やメールで問合せした際に、門脇様に迅速かつ丁寧に
ご対応いただき、安心して依頼できました。
発送後のご連絡もいただき、フォローもしっかりしている
企業様だと感じました。
また宜しくお願い致します。','5','/images/enquete/2017/733_cmp_f.jpg','/images/enquete/2017/733_cmp_dm.jpg'],['2017/09/13','/enquete/2017/','734','505','wtn','専門商社','兵庫県','240','少量ＯＫ、価格安というところからメディアボックス様へお願い致しました。迅速！丁寧！なご対応で、あっという間の発送でした。','初めてのＤＭ発送で、しかも小口での依頼でしたので、どこにお願いしたらよいものかと。
不安なまま "少量ＯＫ、価格安" というところからメディアボックス様へお願い致しました。
しかし、そんな不安はすぐに払拭されました。
"迅速！丁寧！"なご対応で、あっという間の発送でした。
その間のポストカードによる細かなご配慮や、発送後の対応など
貴社の仕事に対する取り組む姿勢に関心するとともに
社内でも見習うべきとお伝えしているところです。
今後も是非お願いしたいと思います。
どうぞ、よろしくお願い致します。','5','/images/enquete/2017/734_wtn_f.jpg','/images/enquete/2017/734_wtn_dm.jpg'],['2017/09/26','/enquete/2017/','735','506','yya','専門学校','東京都','7391','モデルを使ってサイトを作ってる会社が多い中、メディアボックスさんのＨＰに掲載されていた女性の笑顔がとても印象的でした。','ＨＰを拝見したときに、モデルを使ってサイトを作ってる会社が多い中、
メディアボックスさんのＨＰに掲載されていた女性の笑顔がとても印象的でした。
また、初めて使わせていただく中で不明点も多かったですが、担当の方は
いつもメールで丁寧にご対応いただき、心強かったです。
また、郵送にて資料を送って頂いていたので、発送手順など、その資料を参照
できたのも良かったと思います。
他社と比べて、金額もとても魅力的でした。
心配りが嬉しい、信頼できる会社でした。','4','/images/enquete/2017/735_yya_f.jpg','/images/enquete/2017/735_yya_dm.jpg'],['2017/09/28','/enquete/2017/','736','507','aks','保険会社','石川県','503','メールや資料がわかりやすく大変参考になりました。','単独でＤＭを出すことが初めてだったので、とまどいがありましたが
メールや資料がわかりやすく大変参考になりました。
しかし、発送期間が少し長く感じましたので、今度は事前に対応していきたいと思います。','4','/images/enquete/2017/736_aks_f.jpg','/images/enquete/2017/736_aks_dm.jpg'],['','/enquete/2017/','737','','tgmb','メーカー','東京都','','','','4','','/images/enquete/2017/737_tgmb_dm.jpg'],['2017/10/09','/enquete/2017/','738','508','skd','眼鏡店','埼玉県','1200','配達までしてくれるので、封書にＤＭを入れたり、宛名シールを貼ったりする手間がない。価格が安かったなどです。','良かった点は、Ａ4ＤＭが目立つこと。配達までしてくれるので、封書にＤＭを入れたり
宛名シールを貼ったりする手間がない。価格が安かったなどです。
良くなかった点は、最初に問い合わせた時に、お客様の住所をテキストファイル
では受け取れないので、エクセルにしてから送ってくれと言われたのですが、やり方がわからず
業者に頼んで料金も支払いました。その後、お客様の検索条件を変えたため
また業者に頼むともったいないので、ネットで調べたら変換のやり方がありました。
電話の時に、一言アドバイスがあれば余計な出費はありませんでした。
それからこれは大きな問題ですが、お客様の宛名のデータを送ってから配達されるまでの
時間が長すぎる点です。いつもは検索してすぐに配達するので、メガネを買ったばかりの
お客様にはＤＭが届かないようにしています。ところが今回はそれができなかったために、
普通にお買い求めいただいたお客様が出来上がりのメガネを取りに来た時に、
セールの金額に返金あるいはクレジットカードの訂正という人が数人いました。
宛名のデータだけぎりぎりで送れたらよかったと思います。','4','/images/enquete/2017/738_skd_f.jpg','/images/enquete/2017/738_skd_dm.jpg'],['2017/10/10','/enquete/2017/','739','509','ies','建築事務所','大阪府','2085','今まで自分たちで送付していた時と変らない位の発送料で、ラベルはりや封入などをやって頂けて、とても助かりました。','初めてＤＭ代行をお願いしました。
今まで自分たちで送付していた時と変らない位の発送料で、
ラベルはりや封入などをやって頂けて、とても助かりました。
今まで何日間かかけてずっと封入作業等をスタッフで行っていましたが、
それを全てお任せできて本当によかったです。
メールの対応も親切で返信も早く、とても信頼できました。
ありがとうございました。
お礼の石けんもありがとうございます^_^','4','/images/enquete/2017/739_ies_f.jpg','/images/enquete/2017/739_ies_dm.jpg'],['2017/10/10','/enquete/2017/','740','510','skz','自動車関連事業','愛知県','2124','ＤＭの送付を、ヤマト運輸さんと相談していた所で、FAXを思い出しました。「エッ！！作業してもらってこの価格」と方針変更。','数年前に一度、問い合せしていました。当時はＡ4サイズのＤＭにはなじみ無く、
忘れかけていた頃にFAXの案内をいただきました。
今回、7月末頃から、ＤＭの送付を、ヤマト運輸さんと相談していた所で、FAXを
思い出しました。「エッ！！作業してもらってこの価格」と方針変更。
これからは、印刷もお願いすると、送付の手間もなくなると話してます。
今後は、効果的なＤＭの事も相談しようと思います。
DMのデザインをしていただける方の紹介はありますか？','4','/images/enquete/2017/740_skz_f.jpg','/images/enquete/2017/740_skz_dm.jpg'],['2017/10/11','/enquete/2017/','741','511','rnf','不動産業','東京都','626','安価にＤＭが送れて良かったです。','初めて利用しましたが、安価にＤＭが送れて良かったです。
メールでのやり取りがWEB化すると手間があと1、2回は減るなと思っていました。
全体的には良かったのでまた利用します。','4','/images/enquete/2017/741_rnf_f.jpg','/images/enquete/2017/741_rnf_dm.jpg'],['','/enquete/2017/','742','','tkk','会計事務所','大阪府','','','','4','','/images/enquete/2017/742_tkk_dm.jpg'],['2017/10/24','/enquete/2017/','743','512','tith','医療関連事業','東京都','11539','メールでの対応も早く的確で、ハガキのお礼状をいただくなど安心してお任せすることができました。','初めてのお取引で多少不安もありましたが、
