安心してお任せすることができました。
今回は大変お世話になりました。
ありがとうございました。','4','/images/enquete/2017/743_tith_f.jpg','/images/enquete/2017/743_tith_dm.jpg'],['2017/11/04','/enquete/2017/','744','513','rfk','介護事業','岐阜県','350','一番良い点としては、都度の「連絡」がしっかりとされており進捗状況が把握しやすいと感じました。','印刷データの入稿方法で少し手間が掛かりましたが
