一番良い点としては、都度の「連絡」がしっかりとされており
進捗状況が把握しやすいと感じました。
引き続き、機会がありましたら宜しくお願い致します！','5','/images/enquete/2017/744_rfk_f.jpg','/images/enquete/2017/744_rfk_dm.jpg'],['2017/11/10','/enquete/2017/','745','514','frbm','家具関連事業','石川県','637','メールでのやりとりでしたが、とても分かりやすくご連絡頂き助かりました。','ネットで検索し、御社を見つけました。場所が東郷町で
私の在所の（日進市）となり町という事もありお願いする事にしました。
メールでのやりとりでしたが、とても分かりやすくご連絡頂き助かりました。
また、お願いするかと思いますので、よろしくお願い致します。','4','/images/enquete/2017/745_frbm_f.jpg','/images/enquete/2017/745_frbm_dm.jpg'],['2017/11/16','/enquete/2017/','746','515','wbd','建築業','埼玉県','1116','何より、メール・電話はもとより、手書きのお礼状やオリジナルギフトを届けていただく等、御社の誠実な取り組みに、感じ入ったことをお伝えいたします。','親会社がお世話になっており、初めて弊社のＤＭ発送で利用いたしました。
