ご対応いただき、助かりました。
何より、メール・電話はもとより、手書きのお礼状や
オリジナルギフトを届けていただく等、御社の誠実な
取り組みに、感じ入ったことをお伝えいたします。
お世話になりました。又、よろしくお願いいたします。','5','/images/enquete/2017/746_wbd_f.jpg','/images/enquete/2017/746_wbd_dm.jpg'],['2017/11/27','/enquete/2017/','747','516','mbd','デザイン事務所','東京都','5000','営業メールや電話がないのも煩わしさが無く好印象です。','初めてのDM発送代行、不安も不手際もありましたが、
