価格は相見積をとらなかったので他社との比較はしていませんが、
十分に安いと感じました。','5','/images/enquete/2017/748_anb_f.jpg','/images/enquete/2017/748_anb_dm.jpg'],['2017/12/05','/enquete/2017/','749','518','kkh','清掃関連事業','大阪府','13529','宛名データの文字化け報告もしっかりいただけて、助かりました。','初めての利用で、若干不安でしたが、見積の段階から丁寧に対応していただき
