大変スムーズにＤＭ発送が出来ました。
小口の発注数にも関わらず、お値段も良心的で助かりました。
有り難うございました。','4','/images/enquete/2017/753_lbc_f.jpg','/images/enquete/2017/753_lbc_dm.jpg'],['2017/12/20','/enquete/2017/','754','521','rgsc','旅行関連事業','奈良県','349','料金は、当然かなり高くなると思いますが、それでもＯＫですので対応して頂くことは出来ないでしょうか。','当クラブの会報は、わずかですが、海外にも発送先があります。
