ありがとうございます。ご対応頂いた担当者様も、何度もお問合わせ
をしたにも関わらず、心良くお答え頂き、しっかりと理解した上で作業できました。
今後とも宜しくお願い致します！','5','/images/enquete/2018/759_ktwc_f.jpg','/images/enquete/2018/759_ktwc_dm.jpg'],['2018/01/23','/enquete/2018/','760','525','myk','建設業','滋賀県','50','地元の業者よりも断然安く、発送までの期間も早かったので、迷うことなく決定することができました。','小ロットのダイレクトメールの案件でしたが、とても親切に、分かりやすく対応して頂きました。
社内稟議を作成するため、地元の業者さんにも、見積を依頼しましたが、メディア
ボックスさんの方が断然安く、発送までの期間も早かったので、迷うことなく
決定することができました。発送リストの送り方や、発送物の送付方法など
分かりやすく説明して頂けたのでスムーズにできました。またダイレクトメールでした
ので、配送完了が分かるクロネコＤＭ便で送って頂き、ＤＭ便番号も教えて
頂いたので大変助かりました。次回もＤＭ案件がありましたら、お願いすると
