紙資源節約のためにも、リピーターには不要かと思います。
今後ともどうぞ宜しくお願い致します。','5','/images/enquete/2018/761_hstd_f.jpg','/images/enquete/2018/761_hstd_dm.jpg'],['2018/02/08','/enquete/2018/','762','527','rbb','食品関連事業','大阪府','50','資料など送付いただき、分かりやすく丁寧に対応いただきありがとうございました。','資料など送付いただき、分かりやすく丁寧に対応いただきありがとうございました。
印刷をお願いすると、当然のことながら5営業日になってしまう
のが少し残念ですが、件数と価格を考えるとありがたいです。
お客様にＤＭが届いたのかどうか弊社側で確認できるシステム
（問い合わせNoなど）があればいいなと思います。既にございましたら
申し訳ございません。確認方法を教えていただければ助かります。
今後ともよろしくお願いいたします。
（石鹸、ありがとうございました。）','5','/images/enquete/2018/762_rbb_f.jpg','/images/enquete/2018/762_rbb_dm.jpg'],['','/enquete/2018/','763','','swg','住宅関連事業','大阪府','','','','3','','/images/enquete/2018/763_swg_dm.jpg'],['2018/02/21','/enquete/2018/','764','528','shs','システム会社','東京都','758','電話やメール対応が丁寧で、聞きたいことをシンプルかつ的確に答えてくださったことで不安を払しょくできたことが、御社を選定した一番大きな要因でした。','会社から顧客へＤＭを出すにあたり、安価な代行業者を探していたところ、
安価にも関わらず、発送だけでなく封入も宛名も一括で依頼できる御社をネットで見つけました。
おかげで、全て自分で行うつもりでいましたが、大幅な時間削減を図ることができました。
他社でもっと安価なところもあったのですが、サイトにある電話番号にかけてもコールが長いところが多く、
 顔が見えない中で、電話やメール対応が丁寧で、聞きたいことをシンプルかつ的確に答えてくださったことで 
不安を払しょくできたことが、御社を選定した一番大きな要因でした。
紙媒体での情報や広告は減少傾向にありながらも、必要な情報資源であると考えてますので
御社におかれましては今後もより一層の発展を期待しております。','4','/images/enquete/2018/764_shs_f.jpg','/images/enquete/2018/764_shs_dm.jpg'],['2018/02/22','/enquete/2018/','765','529','hrss','製造メーカー','東京都','853','ご丁寧なメール、TELに安心してお任せすることができました。','この度はありがとうございました。
