資料（サンプルとかはありがたいです！）が多すぎて、止めようかとも
思ったので、資料の多さがおっくうに感じました。
せっけん、ありがとうございます。是非使わせてもらいます。','4','/images/enquete/2018/775_ntnn_f.jpg','/images/enquete/2018/775_ntnn_dm.jpg'],['2018/05/19','/enquete/2018/','776','537','akrn','建設業','大阪府','2275','マメな手紙も、お礼のセッケン等、隅々まで気をつかっている印象で見習いたい点も多くありました。','最初に不明な点を電話で問い合わせしたが
