マメな手紙も、お礼のセッケン等、隅々まで気をつかっている印象で
見習いたい点も多くありました。','4','/images/enquete/2018/776_akrn_f.jpg','/images/enquete/2018/776_akrn_dm.jpg'],['2018/05/23','/enquete/2018/','777','538','onuk','製造業','大阪府','305','発注の流れも分かりやすく、こちらの急な変更にも対応いただき助かりました。','発送まで最初は長いかなと思いましたが、値段を考えると致し方ないと思います。
