出来上がったものをまとめて郵送で送るという形をとっていました。
これには人員と時間を要してプリンターも占領してしまう上に、目に見えないコストもかかっていました。
今回、メディアボックス様の存在を知り、初めて利用させていただきまして、印紙代・宛名シール代
・印刷代・人件費・配送料をまとめてお任せ出来るので、かなりのコスト削減ができたという印象です。 
前もってわかりやすく入稿手順を知らせていただいたお陰で、比較的スムーズに入稿出来たと思います。
アクションごとにメールでご連絡いただき、実際目に見えなくとも安心して業務を任せられました。
また、担当者の方から直筆のお便りをいただき、とても嬉しかったです。
この度は本当に助かりました。またお願いしたいです。','5','/images/enquete/2019/853_jnu_f.jpg','/images/enquete/2019/853_jnu_dm.jpg'],['2019/06/26','/enquete/2019/','854','599','met','医療機器関連','東京都','335','レスポンスも早く、お電話での問い合わせにも非常に丁寧に返答を頂き、とても助かりました。','今回は迅速にご対応頂きましてありがとうございます。
価格が安いだけでなく、レスポンスも早く、お電話での問い合わせ
にも非常に丁寧に返答を頂き、とても助かりました。
資料を送って下さったり、メールでこまめにご連絡を頂けたので
安心してお任せすることができました。
これからも御社の細やかなサービスを是非利用させて頂きたいと思います。
ただ、1点だけ、予備部材10部が着払いもしくは廃棄なのが残念でした。
料金に含めても、返送して頂けたら嬉しかったかなと思いました。
（弊社にとっては大切なカタログでしたので…。）
それ以外は本当に感謝しかありません。ありがとうございました。','5','/images/enquete/2019/854_met_f.jpg','/images/enquete/2019/854_met_dm.jpg'],['2019/07/02','/enquete/2019/','855','600','knt','自然食品関連','奈良県','590','色々フォローのお便りを送って頂くより、そちらに戻ってきたDM類を私共に送り返して頂ける方がありがたい。','色々フォローのお便りを送って頂くより、そちらに戻ってきた
DM類を私共に送り返して頂ける方がありがたい。
