石けんもありがたいし、御社が障害者の支援に取り組んで
いることは理解できるものの物は別に不要です。
「商品サービス」に力を入れて頂けると間違えなく
次回も利用する。「多分…」ではなく。よろしくお願いします。','4','/images/enquete/2019/855_knt_f.jpg','/images/enquete/2019/855_knt_dm.jpg'],['','/enquete/2019/','856','','map','コンサルティング関連','東京都','1666','','','4','','/images/enquete/2019/856_map_dm.jpg'],['2019/07/05','/enquete/2019/','857','601','kkd','食品関連','東京都','960','うちのシステムのため、支払いまで時間がかかってしまうので、できれば翌月請求書払も検討いただけたらうれしいです。','大変ご丁寧な対応ありがとうございました。
