この度はありがとうございました。','5','/images/enquete/2019/859_sta_f.jpg','/images/enquete/2019/859_sta_dm.jpg'],['','/enquete/2019/','860','','ozf','議員','神奈川','346','','','5','','/images/enquete/2019/860_ozf_dm.jpg'],['2019/08/04','/enquete/2019/','861','603','kkm','理容関連','愛知県','100','金額に対してしっかりとした取り組みが信頼できる会社でした。','この度はご利用させて頂きありがとうございました。
