信頼できる会社でした。今後とも宜しくお願いします。','5','/images/enquete/2019/861_kkm_f.jpg','/images/enquete/2019/861_kkm_dm.jpg'],['2019/08/07','/enquete/2019/','862','604','bjt','コンサルティング関連','東京都','2782','価格も良心的で、なおかつ、やりとりが分かりやすく、スピーディでした。','とても丁寧な対応ありがとうございました。
価格も良心的で、なおかつ、やりとりが分かりやすく、スピーディでした。
こちらから不明点が思いつかなかったのもさすがであると思いました。
ご対応いただいた村上様、水野様、神戸様誠にありがとうございました。','4','/images/enquete/2019/862_bjt_f.jpg','/images/enquete/2019/862_bjt_dm.jpg'],['2019/08/08','/enquete/2019/','863','605','hsb','報道関連','北海道','87','発送後、請求対応もご検討くださればありがたいです。','振込期限指定、かつ確認後発送が原則となっていますが、
会社によっては振込指定を数日後等短いスパンですることが
通常の経理フローでは難しい場合もあろうかと思います。
今回初めての取り引きでやむを得ない部分もありますが、
発送後、請求対応もご検討くださればありがたいです。','4','/images/enquete/2019/863_hsb_f.jpg','/images/enquete/2019/863_hsb_dm.jpg'],['','/enquete/2019/','864','','fhs','農業関連','兵庫県','500','','','4','','/images/enquete/2019/864_fhs_dm.jpg'],['2019/09/08','/enquete/2019/','865','606','has','税務関連','神奈川','597','ご丁寧にメールを下さり、状況が分かるので、安心できました。','いつもお世話になっております。
ご丁寧にメールを下さり、状況が分かるので、安心できました。
本当にありがとうございました。
今後とも宜しくお願い申し上げます。','4','/images/enquete/2019/865_has_f.jpg','/images/enquete/2019/865_has_dm.jpg'],['2019/09/10','/enquete/2019/','866','607','sv','不動産関連','東京都','17071','自社封入作業がなくなり、なおかつ安く対応していただけて、とても助かりました。','今までDMは、社員が封入して発送しておりました。（今回初めて、DM発送代行業者様を利用しました。）
今回もそのつもりでしたが、何気なくHPを検索したところ、御社のHPが
目につきました。弊社からクロネコヤマトさまに依頼すると、1通100円でした。
㈱メディアボックスさまに、封入から全てお任せすると、1通76円でした。
封入作業もなく、なおかつ安く対応していただけて、とても助かりました。
(9/2に発送していただき、9/3からすでに何件か反響もいただいております。)
第2弾のDMも予定しております。また、お願いできればと思っております。
他社さまから見積をとることなく、御社にお任せしましたが、
私の目に狂いはありませんでした！
HPに金額が細かく載っており、良かったです。ありがとうございました!!','5','/images/enquete/2019/866_sv_f.jpg','/images/enquete/2019/866_sv_dm.jpg'],['','/enquete/2019/','867','','en','ダンス関連','群馬県','3543','','','4','','/images/enquete/2019/867_en_dm.jpg'],['2019/09/10','/enquete/2019/','868','608','mia','美容関連','群馬県','1225','電話での対応がとても分かりやすく親切でした。','電話での対応がとても分かりやすく親切でした。
またお願いしたいです。
また、今回の後日のオリジナル石けんや、メッセージの紙等、
大変びっくりしました。
お心づかいをとても感じます。
ありがとうございます。','5','/images/enquete/2019/868_mia_f.jpg','/images/enquete/2019/868_mia_dm.jpg'],['2019/09/13','/enquete/2019/','869','609','ema','不動産関連','山口県','380','担当の方が決まっている為スムーズで、対応が親切、丁寧でした。','この度初めて利用させて頂きました。
担当の方が決まっている為スムーズで、対応が親切、丁寧でした。
見積りを依頼した後、御案内状で資料をいただけた事、
申込み後に村上様から直筆のお手紙が届いた事、
細かいですがDM料金を振込みした後にすぐに入金確認メールが
届いた事、きちんと仕事をされていると感じました。
大変満足です。
そして村上様、ありがとうございました。
これからも宜しくお願いします。','5','/images/enquete/2019/869_ema_f.jpg','/images/enquete/2019/869_ema_dm.jpg'],['2019/09/15','/enquete/2019/','870','610','mkg','医療関連','大阪府','2800','考えていたよりも簡単でわかり易かったです。','今回、代行業者様に依頼したのは初めてですが、
考えていたよりも簡単でわかり易かったです。
次回もぜひ利用させていただきます。','5','/images/enquete/2019/870_mkg_f.jpg','/images/enquete/2019/870_mkg_dm.jpg'],['2019/09/23','/enquete/2019/','871','611','adb','広告代理店','東京都','536','発注前に「宛名印字見本」をご依頼しましたところ要望に応えていただき助かりました。','ご担当いただいた村上純代様のご対応が
とてもていねいで気持ちの良いものでした。
ありがとうございました。
また、こちらで宛名データ作成のために
発注前に「宛名印字見本」をご依頼しましたところ
要望に応えていただき助かりました。
ご作業いただいた方、ありがとうございました。
そういうご対応にも「ここにお願いしよう」と思いました。','5','/images/enquete/2019/871_adb_f.jpg','/images/enquete/2019/871_adb_dm.jpg'],['2019/09/25','/enquete/2019/','872','612','rym','法律関連','群馬県','1453','初めての外注で不安もありましたが、都度丁寧なメールをいただき、迅速に発送することが出来ました。','今までDMや挨拶状を自社内で封入・宛名ラベル張り、発送までしていましたが、
事前準備をしていても、通常業務をしながらの作業は大変負担を感じていました。
今回、急きょ挨拶状を1500部ほど発送することになり、慌てて外注業者を探した
ところ、御社のHPに巡り合い依頼いたしました。
初めての外注で不安もありましたが、都度丁寧なメールをいただき、迅速に発送することが出来ました。
価格も安く、むしろ申し訳ないほどでしたが、年に1回ないし2回ほどDM発送を行って
いるので、またお願いしたいと思います。','4','/images/enquete/2019/872_rym_f.jpg','/images/enquete/2019/872_rym_dm.jpg'],['2019/10/10','/enquete/2019/','873','613','mdt','エネルギー関連','東京都','1391','初回の利用後、こちらのアンケートを返信する前に、既に2度目の発送を依頼しております。','初回の利用後、こちらのアンケートを返信する前に、既に2度目の発送を依頼しております。
毎回、ご迷惑をおかけしておりますが、よろしくお願い致します。','5','/images/enquete/2019/873_mdt_f.jpg','/images/enquete/2019/873_mdt_dm.jpg'],['2019/10/14','/enquete/2019/','874','614','vnr','音楽関連','神奈川県','1000','ご丁寧にご対応頂き大変に有難く存じます。','初めて、こういったサービスを利用し、不安でありましたが、
