大変満足しています。 今後もぜひ使わせて頂きたいと思います。','5','/images/enquete/2019/877_otr_f.jpg','/images/enquete/2019/877_otr_dm.jpg'],['2019/11/06','/enquete/2019/','878','616','kkg','行政書士','静岡県','125','発送までとてもスムーズに進み、安心していられました。','いつもすばやい対応をしてもらいました。
発送までとてもスムーズに進み、安心していられました。
ありがとうございました。
ただ1つ疑問が… 
何度もハガキや資料(今回の石けん)送ってきてくれますが、
そんなにまでしてコスト合うんですか。。
そこだけ心配でした。またよろしくお願いします。','5','/images/enquete/2019/878_kkg_f.jpg','/images/enquete/2019/878_kkg_dm.jpg'],['2019/11/25','/enquete/2019/','879','617','srk','社労士','大阪府','306','値段を比較的安くできたので、概ね満足しています。','発送までに少し時間がかかったのがマイナス点ですが、
それ以外は基本的にていねいに対応して頂きました。
値段を比較的安くできたので、概ね満足しています。','4','/images/enquete/2019/879_srk_f.jpg','/images/enquete/2019/879_srk_dm.jpg'],['','/enquete/2019/','880','','bai','医療関連','大阪府','5000','','','5','/images/enquete/2019/880_bai_f.jpg','/images/enquete/2019/880_bai_dm.jpg'],['2019/12/18','/enquete/2019/','881','618','ahi','保険関連','愛知県','663','メールやハガキで丁寧なごあいさつがあり、安心できました。','メールやハガキで丁寧なごあいさつがあり、安心できました。
発送までの流れも、ホームページや最初のメール説明で十分わかりやすかったので、
電話で問合わせることもなくできました。
進捗の報告メールもありがだいです。
ビニール封筒も市販で買うと1枚7円くらいですので、4円は安いですね。
お世話になりました。','5','/images/enquete/2019/881_ahi_f.jpg','/images/enquete/2019/881_ahi_dm.jpg'],['','/enquete/2019/','882','','ace','NGO関連','東京都','1065','','','3','/images/enquete/2019/882_ace_f.jpg','/images/enquete/2019/882_ace_dm.jpg'],['2020/01/21','/enquete/2020/','883','619','ks','経理関連','大阪府','1502','最後まで不安なく手続きできました。','データアップロードが難しかったです。入口がわかりにくかった。
しかし、アップロードの方法をはじめ、
その後の手続きまで丁寧に教えて下さり、
最後まで不安なく手続きできました。
また利用したいと思います。','5','/images/enquete/2020/883_ks_f.jpg','/images/enquete/2020/883_ks_dm.jpg'],['2020/01/23','/enquete/2020/','884','620','ash','ホテル関連','熊本県','2499','大変、丁寧かつ迅速にご対応いただきありがとうございました。','今回初めて利用させていただきました。
他県業者さんとのやり取りで不安もありましたが、大変、丁寧かつ迅速にご対応いただきありがとうございました。
作業場に事前に封入順を伝える方法が、文章でどのように伝えたらいいのか分からず
メールの返信が遅くなってしまい申し訳ありませんでした。
見積りをお願いしてから封入れ・発送まで作業に携わっていただいたメディアボックスの
全てのスタッフの方にお礼申し上げます。
以前頼んでいた発送業者より大幅にコストも削減でき、専門業者のプロは対応も作業スピードも全然違うなと実感しました。
また、心暖まるプレゼントまでお送りいただきとても嬉しい気持ちになりました。
「ありがとう石鹸」の作業風景も微笑ましく、私の障害がある長男にもこのような職場で働けたらいいなと思いました。
また次回もお願い出来ればと思いますので、宜しくお願いいたします。','5','/images/enquete/2020/884_ash_f.jpg','/images/enquete/2020/884_ash_dm.jpg'],['2020/02/13','/enquete/2020/','885','621','ym','住宅関連','岐阜県','248','スムーズに発送までいくことが出来たので、今後も利用していきたいと感じました。','今回初めてメディアボックスさんをご利用させていただいて、
スタッフの電話やメールでの対応が非常に良くて、
スムーズに発送までいくことが出来たので、
今後も利用していきたいと感じました。','4','/images/enquete/2020/885_ym_f.jpg','/images/enquete/2020/885_ym_dm.jpg'],['2020/02/25','/enquete/2020/','886','622','aip','エネルギー関連','東京都','1000','見積りやメールの対応が早く、手書きのハガキも頂き、信頼できる会社だと思いました。','今まで、宛名シールとバーコードラベルを1000枚近く、弊社で貼ってDM便を
