メディアボックスさんに頼んでよかったです。見積りやメールの対応が早く、
手書きのハガキも頂き、信頼できる会社だと思いました。
また発注する機会がありましたら、宜しくお願い致します。','4','/images/enquete/2020/886_aip_f.jpg','/images/enquete/2020/886_aip_dm.jpg'],['','/enquete/2020/','887','','otc','語学研修','愛知県','110','','','5','/images/enquete/2020/887_otc_f.jpg','/images/enquete/2020/887_otc_dm.jpg'],['','/enquete/2020/','888','','tps','葬儀関連','東京都','3362','','','5','','/images/enquete/2020/888_tps_dm.jpg'],['2020/02/28','/enquete/2020/','889','623','snx','建築関連','千葉県','1800','急ぎで発送を考えていた為、少し発送までの期間は長め…？という印象でした。','相場が分からないので、何とも言えませんが、
急な依頼を急ぎで発送を考えていた為、
少し発送までの期間は長め…？という印象でした。
価格は安い？ような印象でしたので、
お願いしましたが、相場が分かりません…','5','/images/enquete/2020/889_snx_f.jpg','/images/enquete/2020/889_snx_dm.jpg'],['','/enquete/2020/','890','','erm','精密機器関連','東京都','425','','','5','/images/enquete/2020/890_erm_f.jpg','/images/enquete/2020/890_erm_dm.jpg'],['2020/03/11','/enquete/2020/','891','624','fsk','商工会議所','静岡県','3864','ご丁寧なメールやお手紙もいただき、嬉しかったです。','早急にご対応くださり、ありがとうございました。
 ご丁寧なメールやお手紙もいただき、嬉しかったです。
安心してお願いすることができました。
ありがとうございました！！','4','/images/enquete/2020/891_fsk_f.jpg','/images/enquete/2020/891_fsk_dm.jpg'],['','/enquete/2020/','892','','wmj','IT関連','東京都','47','','','4','/images/enquete/2020/892_wmj_f.jpg','/images/enquete/2020/892_wmj_dm.jpg'],['2020/03/25','/enquete/2020/','893','625','sk','印刷関連','大阪府','2423','この度初めて貴社のサービスを利用いたしました。','今まで自社内で発送作業を行っておりましたが、部数が多く
