見積りから発送完了のご連絡まで、ご担当いただきました長屋様には
丁寧にご対応いただき、大変助かりました。
今後とも、何卒よろしくお願い申し上げます。','4','/images/enquete/2020/893_sk_f.jpg','/images/enquete/2020/893_sk_dm.jpg'],['','/enquete/2020/','894','','tjm','地図情報関連','東京都','765','','','4','','/images/enquete/2020/894_tjm_dm.jpg'],['2020/04/22','/enquete/2020/','895','626','ymd','印刷関連','長野県','276','迅速なご対応ありがとうございました。','迅速なご対応ありがとうございました。
以前までは郵便で送っていたため、こちらの段取りが悪く、
お手数をおかけしましたが、次回以降はスムーズにお願い
できると思いますので、その際はよろしくお願いいたします。
なお、弊社移転に伴い、住所・TEL等変わりますので、
追ってご連絡いたします。','4','/images/enquete/2020/895_ymd_f.jpg','/images/enquete/2020/895_ymd_dm.jpg'],['','/enquete/2020/','896','','ass','不動産関連','神奈川県','1037','','','5','/images/enquete/2020/896_ass_f.jpg','/images/enquete/2020/896_ass_dm.jpg'],['2020/05/13','/enquete/2020/','897','627','ysk','コンサルティング関連','東京都','1499','(プリントパック～発送業者)という従来のこころみより、納期・価格・対応、すべて満足しています。','以前から、御社さまのウワサは聴いておりました。
(プリントパック～発送業者)という従来のこころみより、
納期・価格・対応、すべて満足しています。担当をおいていただいて
いるのも心強いです。現在は、1500～2000部の発送ですが、
