封入も少し心配でしたが、きれいな状態で届き、また次回
からもお願いしたいなと思います。
ありがとうございました。','5','/images/enquete/2020/899_trt_f.jpg','/images/enquete/2020/899_trt_dm.jpg'],['2020/05/16','/enquete/2020/','900','630','tki','介護関連','香川県','91','迅速な対応をありがとうございました。','この度迅速な対応をありがとうございました。
新型コロナウィルスにより、新しい形の営業方法を行おうと利用させて頂きました。
複数回の見積り依頼、申し訳ございませんでした。
まだまだコロナウィルスの影響があるかもしれませんが、ご自愛くださいませ。
本当にありがとうございました。また、宜しくお願い致します。','5','/images/enquete/2020/900_tki_f.jpg','/images/enquete/2020/900_tki_dm.jpg'],['','/enquete/2020/','901','','rnn','ガス器具関連','静岡県','119','','','4','/images/enquete/2020/901_rnn_f.jpg','/images/enquete/2020/901_rnn_dm.jpg'],['2020/06/12','/enquete/2020/','902','631','nib','ガラス関連','東京都','695','想像以上のスピードで作業を進めて下さり、本当に感謝しております。','在宅勤務の中、短納期の依頼となり、スムーズにいくか
心配したのですが、想像以上のスピードで作業を進めて
下さり、本当に感謝しております。
データ管理等もきちんとされているのも安心でした。
また何かございましたら、よろしくお願いいたします。','5','/images/enquete/2020/902_nib_f.jpg','/images/enquete/2020/902_nib_dm.jpg'],['2020/06/19','/enquete/2020/','903','632','krk','社団法人','京都府','516','メールでの対応は迅速で丁寧で、また自筆の葉書も送ってくださり、非常に感激しました。','今回、初めて印刷・発送をお願いさせていただきました。
