また自筆の葉書も送ってくださり、非常に感激しました。
仕上がりについては大満足でした。
価格はやや高い印象がありましたが、総合すると依頼して良かったと
思います。今度とも、どうぞよろしくお願いします。','5','/images/enquete/2020/903_krk_f.jpg','/images/enquete/2020/903_krk_dm.jpg'],['','/enquete/2020/','904','','sds','エネルギー関連','東京都','370','','','4','','/images/enquete/2020/904_sds_dm.jpg'],['2020/07/13','/enquete/2020/','905','633','nsd','製菓関連','東京都','166','進捗について細やかにメール頂き、安心して作業を進める事が出来ました。','初めて使わせて頂きました。
