あった様に相談にのって対応して頂けました。
料金もとても安く、対応も丁寧で助かりました。
コストを安く出来たので、またDMを発送しようと思います。
ありがとうございました。','5','/images/enquete/2020/910_hds_f.jpg','/images/enquete/2020/910_hds_dm.jpg'],['2020/08/27','/enquete/2020/','911','637','kdk','同窓会','神奈川県','429','工期短縮のエキストラ（+10％）が掛りましたが約1週間で宅配をしていただき助かりました。','お世話になりました。
工期短縮のエキストラ（+10％）が掛かりましたが約1週間で
宅配をしていただき助かりました。
資料印刷については、貴社のリードタイム(約1週間)が思いの外長く依頼できませんでした。
プリント見本等送っていただき印刷状態(とくにカラー)も良く、できれば
DM代行とセットで依頼したいのですが、上記リードタイムがネックになりそうです。
些末な事ですが、残部材返送の着払い料金￥930は高過ぎると思いました。
この点はビジネス・ライクすぎるのでは？','4','/images/enquete/2020/911_kdk_f.jpg','/images/enquete/2020/911_kdk_dm.jpg'],['2020/09/04','/enquete/2020/','912','638','tbs','照明設備関連','東京都','2644','大量のDM発送は初めてでしたので、いろいろと調べて御社に決定いたしました。','この度はお世話になりました。
