今後とも何卒宜しくお願い申し上げます。','5','/images/enquete/2020/920_ytj_f.jpg','/images/enquete/2020/920_ytj_dm.jpg'],['2020/11/06','/enquete/2020/','921','646','syk','食品関連','東京都','1624','電話とメールだけでのやりとりでしたが、資料のご提供・お見積も含め、レスポンスが早く丁寧でとても助かりました。','今まで、印刷を外注し自社でDMラベル印刷から貼り作業を行っておりましたが、
