ありがとうございました。','5','/images/enquete/2020/930_hrn_f.jpg','/images/enquete/2020/930_hrn_dm.jpg'],['2020/12/14','/enquete/2021/','931','656','rjt','同窓会','神奈川県','300','宛名データを送るタイミングの説明資料が分かり難いです。','①封筒の印刷もお願いしましたが、出力見本のFAX送付は必要なのでしょうか？
最近はFAXの無い家もあるので、コンビニからFAXする方も多いのではないでしょうか。
PDFファイル送付で、FAX送付の代用になると助かります。
②宛名データを送るタイミングの説明資料が分かり難いです。
見積書に「ご支給頂く部材は、データご入稿翌日までに到着する様
ご発送下さい」と書いてありますが、部材の送付と宛名データの送付のタイミングを
当方で調整する必要性が良く分かりません。宛名データは
作成出来次第アップロードして良いという流れに出来ないですか？ご検討下さい。','5','/images/enquete/2021/931_rjt_f.jpg','/images/enquete/2021/931_rjt_dm.jpg'],['2020/12/15','/enquete/2021/','932','657','oks','アミューズメント関連','大阪府','434','数が少なく大手では対応してもらえないことがわかり困っていたところで御社をみつけました。','初めてDMを制作したのですが、
数が少なく大手では対応してもらえないことがわかり
困っていたところで御社をみつけました。
とても丁寧にご対応頂き安心できました。ありがとうございました!!
見つもりだけで、手書きのお便りを送って頂いたり、資料やおまけ
まで送って頂き、費用も格安なので心配になるほどです。。
またDMを作ることになった時は、宜しくお願い致します。','4','/images/enquete/2021/932_oks_f.jpg','/images/enquete/2021/932_oks_dm.jpg'],['2020/12/28','/enquete/2021/','933','658','kyk','税理士関連','大阪府','745','色々と対応を快くしていただき、大変感謝しています。','ありがとうございました。
色々と対応を快くしていただき、大変感謝しています。','4','/images/enquete/2021/933_kyk_f.jpg','/images/enquete/2021/933_kyk_dm.jpg'],['2021/01/19','/enquete/2021/','934','659','knp','コンサルティング関連','兵庫県','756','管理者による感染対策のもと、真心こめて作っていただいているのが商品から感じとれます。','ありがとうございました。
「ありがとう石鹸」もありがとうございます。
子どもが喜びます。
マスクを利用できない利用者もいると思います。
管理者による感染対策のもと、真心こめて作っていただいて
いるのが商品から感じとれます。
是非、継続して下さい。','5','/images/enquete/2021/934_knp_f.jpg','/images/enquete/2021/934_knp_dm.jpg'],['2020/01/22','/enquete/2021/','935','660','kks','産廃関連','山梨県','367','利用方法も分かったので、また利用させていただきます。','初めての利用のため、発送までの手順が少し戸惑いましたが、
利用方法も分かったので、また利用させていただきます。','4','/images/enquete/2021/935_kks_f.jpg','/images/enquete/2021/935_kks_dm.jpg'],['2021/02/10','/enquete/2021/','936','661','tid','大学','東京都','2014','発送まで終始安心していられたのを実感しております。','実は今回、発送自体を少し迷っていたのですが、やはり発送を外注しようと思いついて
から、知り合いを通じて紹介しもらい、とても短期間に発注させて頂きました。
知り合いの紹介なので当初から問題ないと思っておりましたが、想像以上にやりとりが大変
丁寧で、メールを小まめに頂けたり、合間に御礼のお葉書まで頂いたりと、気持ちよく
対応して頂きました。発送まで終始安心していられたのを実感しております。
次回以降もこのようなことがあれば、発送を是非お願いさせて頂きたいです。どうもありがとうございました。
とても可愛い石鹸まで頂いてしまい恐縮です。喜んで使わせて頂きます。ありがとうございます。','5','/images/enquete/2021/936_tid_f.jpg','/images/enquete/2021/936_tid_dm.jpg'],['2021/02/17','/enquete/2021/','937','662','sk','建設関連','佐賀県','300','価格が安く資料も送って頂きとても分かりやすかった。','〈メディアボックスさんを選んだ理由〉
・いくつかの印刷会社に見積りを出してもらったが、価格が安く
資料も送って頂きとても分かりやすかった。メールの返信もはやくとても助かった。
〈代行会社を利用した理由〉
・毎月のDM印刷・発送に加え、イベント前のDMもあり人手が足り
なかった為。また、代行会社に依頼してもさほど費用がかわらなかった為。
〈メディアボックスさんを利用して…〉
・誤字や画像についてのアドバイスも頂き、とても助かっています！
担当の方がついてくださるのも心強いです。発送までに少し時間は必要かな…とも
思いましたが、今後も利用させて頂きたいと思っています！','5','/images/enquete/2021/937_sk_f.jpg','/images/enquete/2021/937_sk_dm.jpg'],['2021/02/18','/enquete/2021/','938','663','pfk','建材関連','京都府','1000','逐一メールでご連絡を下さったり、とても丁寧で安心できました。','この度はご丁寧なご対応ありがとうございました。
初めての利用で少し不安もありましたが、逐一メールでご連絡を
下さったり、とても丁寧で安心できました。
手間のかかっていた作業を外注に出すことで、作業の効率化ができました。
また機会がありましたら、宜しくお願いします。','4','/images/enquete/2021/938_pfk_f.jpg','/images/enquete/2021/938_pfk_dm.jpg'],['2021/03/01','/enquete/2021/','939','664','kbl','建設機械関連','東京都','1108','次もお願いしよう、と素直に思える対応とスピードでした。','「次もお願いしよう」と素直に思える対応とスピードでした。
ありがとうございました。
