対応が早く（見積も依頼した当日）、その後もDMについての資料を送付いただく等、大変助かりました。
また、注文前後から発送までのやり取りも迅速に対応いただき大変感謝しております。
今後、DM発送の際には是非とも宜しくお願い致します。','5','/images/enquete/2021/941_riz_f.jpg','/images/enquete/2021/941_riz_dm.jpg'],['2021/03/08','/enquete/2021/','942','667','ast','デザイン事務所','京都府','665','すぐにメールの返信もいただけるので、安心して注文することができました。','初めての注文の際、いろいろ質問したにも関わらず
ご丁寧は回答を何度もいただき、大変たすかりました。
すぐにメールの返信もいただけるので、安心して注文することができました。
担当者の方がついてくださるので、すべて把握してくださっていて
スムーズに注文が出来、とてもありがたいです。
また、直筆のお葉書をいただいたり、初回ということで印刷サンプルをご送付いただいたりと、
至れり尽くせりのご対応をいただき感謝しております。
知人からの紹介とはいえ、初めてお願いすることに
多少の不安がありましたが、ご丁寧なご対応に非常に満足しております。
