初めてのDM業者の利用でしたが、費用対効果も良いと思います。','4','/images/enquete/2021/971_ts_f.jpg','/images/enquete/2021/971_ts_dm.jpg'],['2021/07/08','/enquete/2021/','972','694','ksh','ホテル','長野県','532','坂根様の対応がとてもすばらしく安心して進めることができました。','弊社のご担当者坂根様の対応がとてもすばらしく安心して進めることができました。
