気になるのは、もう少し早く発送できたらいいことと、支払いをクレジットカードでできたり、支払期日に余裕があると助かります。社内のルールで振込日が決まっていて、今日は間に合わず、自分で立て替えたのが手間でした。ここがクリアできたら、今後は必ず利用すると思います。','5','/images/enquete/2021/980_ark_f.jpg','/images/enquete/2021/980_ark_dm.jpg'],['2021/08/18','/enquete/2021/','981','700','ymn','乳製品販売','三重県','2226','封入物をきちんとご確認いただき、封入の順序などアドバイスも下さりとても嬉しく思いました。','今回初めてDMを検討し、メディアボックスさんに依頼しました。
明確な見積りとご連絡の迅速さで安心してお任せすることが出来ました。提出したデータの不備も教えていただいたり、こちらの封入物をきちんとご確認いただき、封入の順序などアドバイスも下さりとても嬉しく思いました。(坂根さんありがとうございました)
DMの発送費用としてはおおよそ普通の価格かなぁと思いますが、対応の良さでお値段以上の品質を感じさせていただきました。
またの機会にも是非お願いしたいと思っています。','4','/images/enquete/2021/981_ymn_f.jpg','/images/enquete/2021/981_ymn_dm.jpg'],['2021/08/20','/enquete/2021/','982','701','ukk','広告代理店','東京都','1249','メディアボックスさんが優しく対応してくれることには感謝します。','入社してから初めての案件です。営業活動のために自社チラシを送ることで、最初さっぱりわかりませんが、メディアボックスさんが優しく対応してくれることには感謝します。
そして発送までの流れのご案内や発送までの報告もすごく安心されました。
これからも長くお付き合いしたいと思いますので、今後ともよろしくお願い致します。','5','/images/enquete/2021/982_ukk_f.jpg','/images/enquete/2021/982_ukk_dm.jpg'],['2021/08/25','/enquete/2021/','983','702','tkt','不動産関連','東京都','595','不達の連絡が早めにもらえると有難い','不達の連絡が早めにもらえると有難い','4','/images/enquete/2021/983_tkt_f.jpg','/images/enquete/2021/983_tkt_dm.jpg'],['2021/09/03','/enquete/2021/','984','703','abp','コンサルタント','千葉県','406','お礼のハガキなどお送り頂き、イメージの良い会社だと思いました。','自社でDM印刷から発送まで行うより代行会社を利用した方が安いので今回お願いしました。
市内の印刷会社にDMをお願いした時は発送前のアイディアや色校などきめ細かい対応をして頂けましたが、その分コスト高であるのは事実です。DMの内容によって使いわけを行っていきたいと思います。
何度かお礼のハガキなどお送り頂き、イメージの良い会社だと思いました。質問メールもすぐに返信頂きありがとうございました。','4','/images/enquete/2021/984_abp_f.jpg','/images/enquete/2021/984_abp_dm.jpg'],['2021/09/09','/enquete/2021/','985','704','tks','食品衛生関連','埼玉県','193','ご丁寧な説明を頂いたおかげで、無事に成功したので本当によかったです。','今回、初めてのDM発送ということもあり、非常に心配・不安な点もございましたが、ご丁寧な説明を頂いたおかげで、無事に成功したので本当によかったです。
早速、一部のお客様からDMへの回答も頂いており効果もでてきております。
今後、追加でDMを検討する際は、あらためてご相談させて頂きます。
このたびは大変お世話になりまして、誠にありがとうございました。
今後とも、どうぞよろしくお願い致します。','4','/images/enquete/2021/985_tks_f.jpg','/images/enquete/2021/985_tks_dm.jpg'],['2021/09/10','/enquete/2021/','986','705','myh','園芸関連','岡山県','3558','担当者様の対応がとても良かったので安心できました。','担当者様の対応がとても良かったので安心できました。','5','/images/enquete/2021/986_myh_f.jpg','/images/enquete/2021/986_myh_dm.jpg'],['2021/09/14','/enquete/2021/','987','706','rpt','機械関連','東京都','1001','様々な難題にご対応いただきありがとうございました。','様々な難題にご対応いただきありがとうございました。','5','/images/enquete/2021/987_rpt_f.jpg','/images/enquete/2021/987_rpt_dm.jpg'],['2021/09/24','/enquete/2021/','988','707','fen','教育関連','東京都','39583','分からない点を質問させて頂いた際、丁寧に説明してくださり、安心してお任せすることができました。','検索上位で知り、初めて利用させて頂きました。
