今回初めてDMを利用しましたが、成果が出たら次回も利用したいと思いました。','4','/images/enquete/2021/989_itr_f.jpg','/images/enquete/2021/989_itr_dm.jpg'],['2021/09/25','/enquete/2021/','990','709','abh','不動産関連','茨城県','703','印刷物のイメージをサンプルとして輸送して下さって、封入物の確認ができ、安心しました。','印刷物のイメージをサンプルとして輸送して下さって、封入物の確認ができ、安心しました。
このサービスは、初回のみとお伺いしましたが、次回利用する際も、あったら良いなと思うサービスでした。','5','/images/enquete/2021/990_abh_f.jpg','/images/enquete/2021/990_abh_dm.jpg'],['2021/09/26','/enquete/2021/','991','710','bht','保育関連','千葉県','1551','坂根様、迅速な対応ありがとうございました。','坂根様、迅速な対応ありがとうございました。','4','/images/enquete/2021/991_bht_f.jpg','/images/enquete/2021/991_bht_dm.jpg'],['2021/10/01','/enquete/2021/','992','711','tt','歯科関連','大阪府','16103','細かな進捗報告を度々メールで下さったり、本来は業務外であろう送るDMのデータデザインの誤字を伝えて下さったりし、お客様へお届けする情報を正しくできました。','今回、坂根様という方にご担当頂きました。
細かな進捗報告を度々メールで下さったり、本来は業務外であろう送るDMのデータデザインの誤字を伝えて下さったりし、お客様へお届けする情報を正しくできました。また、お手紙なども別途頂いたり、同封するもののサンプル送付をして頂けたりと遠方企業でありながら安心しておまかせできました。','5','/images/enquete/2021/992_tt_f.jpg','/images/enquete/2021/992_tt_dm.jpg'],['2021/10/08','/enquete/2021/','993','712','kk','金属加工関連','愛知県','1325','依頼してから発送まで、しっかりフォローして頂いた点も評価しており、継続するなら、次も御社にお願いすると思います。','初めてDMを送るので、時間・価格等は比較するものがないので、評価は出来ないが、比較サイトで、弊社が依頼したい条件として、小ロットで安いという内容に合致した事が選定理由となった。依頼してから発送まで、しっかりフォローして頂いた点も評価しており、継続するなら、次も御社にお願いすると思います。','4','/images/enquete/2021/993_kk_f.jpg','/images/enquete/2021/993_kk_dm.jpg'],['2021/10/12','/enquete/2021/','994','713','aqf','音響機器関連','兵庫県','231','複数社比較しましたが、一番親切で信頼できたのが、貴社でした。','当社カタログを初めて送るために利用させて頂きました。
人数が少ないスタートアップベンチャーのため、人手が足りず探したところ貴社をみつけました。
複数社比較しましたが、一番親切で信頼できたのが、貴社でした。そこが決定打です。
専任担当の方もいて、今回は長屋さんにお世話になりましたが、こちらがいく度となく日程変更しても柔軟に対応頂き感謝しています。
ありがとうございました。','5','/images/enquete/2021/994_aqf_f.jpg','/images/enquete/2021/994_aqf_dm.jpg'],['2021/10/13','/enquete/2021/','995','714','knt','機械関連','大阪府','200','急遽変更になった場合でも迅速に対応していただき、信頼できると思った。','メールのやり取りや電話でのやり取りがスムーズで、データ入稿や見積その他のやり取りも早いだけでなく、担当の方がいつも気持ちのよい対応をしてくださり、安心してお任せできると感じた。
また、急遽変更になった場合でも迅速に対応していただき、信頼できると思った。
※アンケートに関しては、FAXだけでなくメールでの回答もできるようになればいいかなと少し思いました。','5','/images/enquete/2021/995_knt_f.jpg','/images/enquete/2021/995_knt_dm.jpg'],['2021/10/14','/enquete/2021/','996','715','prt','医療機器関連','福岡県','168','対応がすばらしかったです。スピーディな対応におどろきました。','対応がすばらしかったです。スピーディな対応におどろきました。
メールでのやりとりだと、少し時間をとられる印象があったので、もう少し簡易的に依頼ができるといいです。
またDM発送する際は依頼させていただきます。
ありがとうございました。','5','/images/enquete/2021/996_prt_f.jpg','/images/enquete/2021/996_prt_dm.jpg'],['2021/10/18','/enquete/2021/','997','716','sbs','地質調査関連','神奈川','423','対応が丁寧で、安心して以来出来ました。','対応が丁寧で、安心して以来出来ました。','5','/images/enquete/2021/997_sbs_f.jpg','/images/enquete/2021/997_sbs_dm.jpg'],['2021/10/27','/enquete/2021/','998','717','dks','建設資材関連','東京都','4000','サンプルや参考書類一式の送付などから、効率化や専門性の高さなどを感じました。','見積りの3時間以内での回答や、サンプルや参考書類一式の送付などから、効率化や専門性の高さなどを感じました。
何社か見積りをお願いした中で、最低価格ではありませんでしたが、お任せしたいと思いました。
この度は、ありがとうございました。
美味しそうな石鹸も届きました。お心遣いありがとうございます。','4','/images/enquete/2021/998_dks_f.jpg','/images/enquete/2021/998_dks_dm.jpg'],['2021/11/02','/enquete/2021/','999','718','amd','工作機械関連','神奈川','8771','担当者の方の対応がとてもよく、ストレス無く、業務を進める事ができました。','担当者の方の対応がとてもよく、ストレス無く、業務を進める事ができました。
またDMを発送するような機会がございましたらお取引させていただきたく存じます。','5','/images/enquete/2021/999_amd_f.jpg','/images/enquete/2021/999_amd_dm.jpg'],['2021/11/11','/enquete/2021/','1000','719','tey','学習塾','愛知県','796','初めて電話した時にとても丁寧ににしっかりと対応して頂き「ここなら安心して任せられる」と思い、他と比較せずにお願いさせていただきました。','今までスタッフを総動員して20時間以上かけていたDM作成をなんとかできないかと思い、DM発送代行業者を探しました。
メディアボックスを選んだ一番の理由は「校舎から近かった」からですが、初めて電話した時にとても丁寧ににしっかりと対応して頂き「ここなら安心して任せられる」と思い、他と比較せずにお願いさせていただきました。また、実際にお願いする際に2回目の電話をした際も、ひと月以上前の電話内容を覚えてくださっていて、とてもスムーズに話が進み本当にありがたく思いました。
作業中についても、こちらのミスで部材の数が少なかったことに対して、即最善の対応をして頂きました。本当にありがとうございます。
おかげさまで、DM作成にかかるスタッフの時間を生徒対応に回すことができるので、これからの塾の生徒指導力アップにもつながりそうです。今後も利用させて頂きます。
この度は本当にありがとうございました。','5','/images/enquete/2021/1000_tey_f.jpg','/images/enquete/2021/1000_tey_dm.jpg'],['2021/11/24','/enquete/2021/','1001','720','oma','教育関連','大阪府','3396','本当に臨機応変に対応してもらえて、こちらの理由による急な変更や細かなお願いにも対応してくださいました。','＜当社の状況＞
業者さんにお願いするのは初めてのことで、時間も限られていました。
約3600名分の個人宛の書類を送付するにあたり、最も気をつけたのが個人情報の取扱いでした。
＜メディアボックスさんに依頼した理由＞
数社に絞り込み、資料を取り寄せて検討した結果、メディアボックスさんにお願いすることになりました。
個人情報の取扱いの厳格さ、大量の書類送付に慣れておられること、そして価格とサービス内容が決め手です。
＜感想＞
まるでコンシェルジュのように、1名の担当さんが最後まで付いてくださいます。
そして、本当に臨機応変に対応してもらえて、こちらの理由による急な変更や細かなお願いにも対応してくださいました。先を見据えたご提案もありがたかったですね。何しろこういう経験がありませんので。
メールでのやりとりの速さにも驚きました。
まさに、さくさく進むといった感じです。
思い描いていた通りに書類が送付され、想像した以上に早く送付先からのレスポンスが届いており、嬉しい悲鳴をあげております。
送付が終わったら、それで終わりではなく、事後連絡等のきめ細かいメールが届きます。ありがたいです。
今後、またDM等の書類送付をお願いするときには、メディアボックスさんしか考えられないです。','5','/images/enquete/2021/1001_oma_f.jpg','/images/enquete/2021/1001_oma_dm.jpg'],['2021/11/26','/enquete/2021/','1002','721','kgj','行政書士事務所','東京都','1000','こまめな連絡や丁寧な資料の送付、その心遣いに対応の素晴らしさを感じました。','何社か見つもり取った中で、1番安かったのが決め手でしたが、実際にお取り引きが始まると、こまめな連絡や丁寧な資料の送付、その心遣いに対応の素晴らしさを感じました。
また機会があればお願いしたいと思います。','5','/images/enquete/2021/1002_kgj_f.jpg','/images/enquete/2021/1002_kgj_dm.jpg'],['2021/11/26','/enquete/2021/','1003','722','mts','システム関連','大阪府','600','始めてのDM作業でしたので低価格＝対応が悪いのではと心配でしていたのですが、
数日間メールでのやりとりをさせて頂き、返答が早く、親切丁寧に説明して頂いたのでスグに不安が払拭されました。','一番驚いたのが価格でした。
他社にも同じ条件で見積りをお願いしたのですが、メディアボックス様の2倍の見積りが上がってきました。
ただ、始めてのDM作業でしたので低価格＝対応が悪いのではと心配でしていたのですが、数日間メールでのやりとりをさせて頂き、返答が早く、親切丁寧に説明して頂いたのでスグに不安が払拭されました。
また、発送前に発送見本を送って頂いたり、DM発送後の未着リストを頂けるなど丁寧な対応に感謝しております。
今後もDM業務が発生した際はお力をお借りすると思います。
今後ともよろしくお願い致します。','5','/images/enquete/2021/1003_mts_f.jpg','/images/enquete/2021/1003_mts_dm.jpg'],['2021/11/26','/enquete/2021/','1004','723','yui','寺院関連','神奈川','162','メディアボックスの宛名ラベルを表記するイメージ図をホームページで探せませんでしたが、担当者に電話すると丁寧に教えてくれました。','当社資料を見込み客にDMするために使わせていただきました。
当初、ネット印刷会社の封入封緘・DMサービスを使う予定でしたが、封筒に当社の社名表記ができず、封筒も送付できないので断念しました。
メディアボックスの宛名ラベルを表記するイメージ図をホームページで探せませんでしたが、担当者に電話すると丁寧に教えてくれました。
当社クラインとはアナログ指向の方が多いので、資料送付は有効です。また、クライアントが発送する案内が多いため、クライアント名を記載した封筒に封入封緘が代行できるサービスがあることを案内してあげたいと思います。','5','/images/enquete/2021/1004_yui_f.jpg','/images/enquete/2021/1004_yui_dm.jpg'],['2021/12/01','/enquete/2021/','1005','724','pap','広告代理店','愛知県','4977','御社のHP内容がDMについて詳しく書かれていて分かりやすかったです。','DM発送は自社内での業務に大きな負担となり、作業軽減のため発送代行を依頼しました。
見積りをいただき、発送料金も自社で発送するよりも低くなりました。
御社のHP内容がDMについて詳しく書かれていて分かりやすかったです。
以前、御社に伺い、透明封筒を購入したことがあり、信頼できると感じました。
電話やメールでの対応もレスポンスよく丁寧にしていただけました。
