ただ、HPが見辛いのと、データのアップロードのしかたをHPにかいておいていただけたらなと思いました。DLのばしょは先にみつけたので、わかればすぐできるので、先に仕方だけ知りたかったです。HPしらべましたが、くわしくはのっていなかった様でした。','5','/images/enquete/2022/1031_sjk_f.jpg','/images/enquete/2022/1031_sjk_dm.jpg'],['2022/05/02','/enquete/2022/','1032','750','ruk','樹脂製品製造販売','埼玉県','1010','他社より少し高い金額の見積りでしたが信頼できそうなメールの返信などで選びました。','DMを郵便局の配送で考えていましたが、料金割引がないという事を知り、御社をHPより見つけました。他社より少し高い金額の見積りでしたが信頼できそうなメールの返信などで選びました。
