勘違いでなければワクワク系を取り組んでいらっしゃいますか？
どうして代行を利用しようと思ったか？は、封入発送・印刷コストを加味しても委託した方が安かったから。
どうして御社か？は、価格＆ていねいさ（ここまで1つ1つ丁寧に対応し、コストをかけて感謝を伝える会社様は無いと思います）是非今後も利用させて頂きます。','5','/images/enquete/2022/1034_tat_f.jpg','/images/enquete/2022/1034_tat_dm.jpg'],['2022/05/18','/enquete/2022/','1035','753','hsd','教育関連','広島県','811','アンケート調査なので、不達分のデータをいただけるのはありがたいです。','学会での調査目的で使用しました。
スムースに発送をすすめるこができ、助かりました。アンケート調査なので、不達分のデータをいただけるのはありがたいです。','4','/images/enquete/2022/1035_hsd_f.jpg','/images/enquete/2022/1035_hsd_dm.jpg'],['2022/05/18','/enquete/2022/','1036','754','pms','保険代理店','東京都','563','安価でありながらサービスが豊富であった為、メディアボックスを利用することにしました。','お客様への認知を高める為、また新規販路を開拓するためにＤＭ発送を社内で検討しておりましたが、右も左もわからなかった他、ＤＭ発送を社内で行うだけの人的余裕がなかった為利用しました。
