資料も送付していただき、DMの完成イメージがわきやすかったです。御社の対応が素晴らしすぎて、自分も見習わなければと思いました。','5','/images/enquete/2023/1088_unj_f.jpg','/images/enquete/2023/1088_unj_dm.jpg'],['2023/08/04','/enquete/2023/','1089','799','wam','コンサルティング','埼玉県','242','一人でやるには大変な枚数を快く受けて下さり、しかもとても丁寧で、今までにないくらい、手厚いサービスを受けました。','今回ネット検索から初めて利用してみました。
というのも元々件数も200～300通ほどだったので、「自分でやった方が良いか？」「少ないと割高にならないか？」というような不安がありました。
一人でやるには大変な枚数を快く受けて下さり、しかもとても丁寧で、今までにないくらい、手厚いサービスを受けました。
今回はテストも兼ねて反応をみながらですが、ぜひまた利用したいと存じます。
