長屋正美様
この度は見積もりから発送まで、スムーズにご対応頂き、誠にありがとうございました。
私自身DM発送をする事が初めてで、右も左も分かりませんでしたが、ご丁寧な説明と郵送して頂いたパンフレットを読みながら、作業を進める事が出来ました。
メールのご返信もすぐに頂き、とても安心する事が出来ました。本当にありがとうございました。','3','/images/enquete/2023/1090_esn_f.jpg','/images/enquete/2023/1090_esn_dm.jpg'],['2023/8/24','/enquete/2023/','1091','801','lnk','人材派遣関連','兵庫県','50','電話やメールの対応が丁寧でわかりやすかったです。','電話やメールの対応が丁寧でわかりやすかったです。
