今後もお世話になりたいと思いました。','5','/images/enquete/2023/1091_lnk_f.jpg','/images/enquete/2023/1091_lnk_dm.jpg'],['2023/9/10','/enquete/2023/','1092','','nrm','建設関連','岡山県','1000','','','5','','/images/enquete/2023/1092_nrm_dm.jpg'],['2023/9/25','/enquete/2023/','1093','802','yor','旅館','長野県','843','専任の担当がつき、丁寧に対応していただけました。','①どうしてDM発送代行会社を利用しようと思ったか？
通常はこれまでハガキのDMしか送っていないので、プリントパックさんで印刷し、弊社内で宛名のみをプリントして送っていました。
今回、100周年記念にあたりマンガ冊子を制作したため、これを梱包して送ることになり、はじめは弊社内で封入・宛名ラベル貼りを行おうとしていましたが、その作業時間を考えると膨大な時間と人の手が必要になることが判明。
信頼できるDM代行業者さんを探して依頼することにしました。
②どうしてメディアボックスさんを選んだか？
Web検索でDM発送代行業者さんを探して複数業者を比較。また、地元のDM代行業者に電話で問い合わせした結果、金額と信頼性の面から御社が一番いいのでは(Webサイトに料金が記載されていた、小ロットから対応してくれる、「営業電話はかけません」との記載等から判断)と思い、見積を依頼しました。他社には見積は依頼していません。
見積りを見て、その安さに正直、びっくりしました。「ヤマト運輸さんの送料も入っていますか？」と尋ねた次第です。
③御社を使用させていただいてどうだったか？
専任の担当がつき、丁寧に対応していただけました。行きすぎないマメな連絡と、手書きのハガキなど心のこもった対応をありがとうございました。地元の業者さんに依頼しようと思ったのは、"顔が見える"仕事になるので安心感があると思っていたからでしたが、担当の方はお顔を存じ上げないだけで、"顔が見える"対応をしていただけたと感じています。
④気になる点
特にありません。次の機会も、ぜひまたよろしくお願いしたいと存じます。','5','/images/enquete/2023/1093_yor_f.jpg','/images/enquete/2023/1093_yor_dm.jpg'],['2023/9/25','/enquete/2023/','1094','803','pmn','不動産関連','東京都','1267','ちょっとした"心遣い"が上手な方(会社)、といったことを大切にしている風土というのが個人的にすごく共感しています。','見積の依頼をしてすぐにお礼の手紙をもらったことに好印象を受けました。
いろいろな資料を送ってくれたのも"ここまでする？"と記憶に残る会社となりました。1番最初に弊社の担当になってくださった方に、TELしたときの印象はそこまでよくありませんでした。声のトーンが少し不愛想に感じました。
でもその後もメール・TELをやり取りする中で、スピード感のある対応、正確な受け答え、分かりやすい説明をしてくれる方だと知ることができ、大変満足しています。
ちょっとした"心遣い"が上手な方(会社)、といったことを大切にしている風土というのが個人的にすごく共感しています。
定期的に発送するDMに関しては、今後御社を利用させていただきます。
長屋さんいつもありがとうございます！！','5','/images/enquete/2023/1094_pmn_f.jpg','/images/enquete/2023/1094_pmn_dm.jpg'],['2023/9/29','/enquete/2023/','1095','804','asr','広告代理店','大阪府','300','親切ていねいなご対応で分からない事にもすぐにお答えいただき、スムーズに注文することができました。','親切ていねいなご対応で分からない事にもすぐにお答えいただき、スムーズに注文することができました。担当の長屋様には大変感謝しております。','5','/images/enquete/2023/1095_asr_f.jpg','/images/enquete/2023/1095_asr_dm.jpg'],['2023/9/30','/enquete/2023/','1096','805','whr','車関連','東京都','7030','実際に取引をしてみると、細かい報連相に信用が高まりました。','・初めてDMで集客を考えました。
