手厚くサンプル提示などのフォローもいただき、とても信頼できると感じた。
また機会がありましたら、是非お願いいたします。','5','/images/enquete/2024/1108_ftr_f.jpg','/images/enquete/2024/1108_ftr_dm.jpg'],['2024/4/12','/enquete/2024/','1109','817','qg','園芸関連','大阪府','214','部数が少なかったですが、毎回お礼の手紙なども送っていただき貴社にして良かったと思います。','他社と比較し安価だったことと、貴社印刷物と弊社印刷物の混同でも問題なく発送していただけたことが決め手となりました。
部数が少なかったですが、毎回お礼の手紙なども送っていただき貴社にして良かったと思います。ありがとうございました。','4','/images/enquete/2024/1109_qg_f.jpg','/images/enquete/2024/1109_qg_dm.jpg'],['2024/4/17','/enquete/2024/','1110','818','spc','ドローン関連','神奈川県','547','HPを見て信頼できる会社だと思い、実際問い合わせしてみて、電話で対応してくた方がすごく丁寧だったので、その時点でお願いしようと決めてました。','今までは、チラシを作成して新聞の折り込みで集客を行っていましたが、今回初めて、特定の会社様にDMを発送する必要があったので、DM発送代行会社をさがしていたところ、メディアボックス様をみつけました。
HPを見て信頼できる会社だと思い、実際問い合わせしてみて、電話で対応してくた方がすごく丁寧だったので、その時点でお願いしようと決めてました。他の会社は電話をかけても全くつながらなかったり、住所データの送り方もわけがわからなかったりと基本的なサービスが全然できていませんでした。
実際貴社にお願いして、見積り対応から発送まで、一切不安なくお任せすることができました。「お客様に対する気配り」が最初から最後までできている貴社の徹底した姿勢は、私自身にも改めて学びになりました。
今後もDM発送の機会がありと思うので、ぜひお願いしたいと思っております。','5','/images/enquete/2024/1110_spc_f.jpg','/images/enquete/2024/1110_spc_dm.jpg'],['2024/4/19','/enquete/2024/','1111','819','nth','不動産関連','愛知県','980','ホームページの情報量が他社に比べダントツで貴社にお願いすることと致しました。','この度はお世話になりました。
ホームページの情報量が他社に比べダントツで貴社にお願いすることと致しました。
1つ1つの心遣いに感謝しております。
発注までの時間が想定よりかかってしまったので、次回からはもう少し余裕をもって発注させていただこうと思います。今後ともよろしくお願い致します。','5','/images/enquete/2024/1111_nth_f.jpg','/images/enquete/2024/1111_nth_dm.jpg'],['2024/5/24','/enquete/2024/','1112','820','jcg','学会','兵庫県','200','今回利用させていただき今までと比べて2割程度配達料が安く済ませることができたと思います。','今回初めてメディアボックスを利用させていただきました。今までY運輸のDM便を使っていたのですが、取扱い方法が変わり本社で審査し、それから判断して発送するようになるということで、手間が非常にかかるということで他の方法で発送できないかwebサイトを探していました。メディアボックスは200部程度の少部数でも扱っていただけるのでお願いできないか調べていました。当方は学会事務局をしており、学会誌や研究報告など、年数回の発送をする機会があります。担当の方が丁寧にお教えいただき、無事今回発送することができました。メディアボックスさんは窓口担当の方が丁寧なので今後も利用させていただきたいと思います。
今回利用させていただき今までと比べて2割程度配達料が安く済ませることができたと思います。これも助かりました。今後ともよろしくお願いします。','5','/images/enquete/2024/1112_jcg_f.jpg','/images/enquete/2024/1112_jcg_dm.jpg'],['2024/5/31','/enquete/2024/','1113','821','ld','介護関連','栃木県','272','少ない発送部数でしたが、丁寧にご対応頂き、大変感謝しております。','少ない発送部数でしたが、丁寧にご対応頂き、大変感謝しております。','5','/images/enquete/2024/1113_ld_f.jpg','/images/enquete/2024/1113_ld_dm.jpg'],['2024/6/18','/enquete/2024/','1114','822','gpg','医療関連','東京都','1000','説明もわかりやすく、質問に対してもきちんと回答していただけたので安心してお願いすることができました。','毎年1000通の封書を郵送する作業業務を外部委託したく探しておりました。
ネットで検索し電話で確認した際、ご担当者の対応がとても丁寧だったことが御社を選んだ理由です。説明もわかりやすく、質問に対してもきちんと回答していただけたので安心してお願いすることができました。契約後も担当者がつき、事前に無駄な作業が生じないようフォローしていただき助かりました。
結果的に封入作業やシール貼り、投函の業務が減り郵便料も以前より安く済みました。なお、契約後の郵送物の連絡事項はメール等に変更していただけるとありがたいです。（封書でなくとも充分ご丁寧な対応をしていただいていると感じます）
来年以降も御社へお願いしたいと思います。この度は、ありがとうございました。','5','/images/enquete/2024/1114_gpg_f.jpg','/images/enquete/2024/1114_gpg_dm.jpg'],['2024/6/20','/enquete/2024/','1115','823','dts','広告代理店','埼玉県','4964','初めてDM代行を利用するため、手順や入稿方法が不安でしたが、質問にもすぐ答えてくださり、信頼感がありました。','初めてDM代行を利用するため、手順や入稿方法が不安でしたが、質問にもすぐ答えてくださり、信頼感がありました。
まだお見積り段階で送付くださった資料が、とても役に立ちました。
また機会があればお願いしたいです。','5','/images/enquete/2024/1115_dts_f.jpg','/images/enquete/2024/1115_dts_dm.jpg'],['2024/6/21','/enquete/2024/','1116','824','nib','建設関連','愛知県','179','DM代行を利用するのは初めてで若干の心配もありましたが、丁寧に対応していただけて、心配もやわらぎました。','DM代行を利用するのは初めてで若干の心配もありましたが、丁寧に対応していただけて、心配もやわらぎました。ただし、目を通さなければならない書類が多く、全体を理解するまでに少々時間がかかりました。送付先によって送付内容が異なったのですが、そのような対応をしていただけたのは有難かったです。DMを受け取った方から、数日以内に実際にお問い合わせをいただき、利用してよかったと思いました。','4','/images/enquete/2024/1116_nib_f.jpg','/images/enquete/2024/1116_nib_dm.jpg'],['2024/6/27','/enquete/2024/','1117','825','ttm','保険関連','大阪府','120','とても対応が良くお値段も良いと紹介していただき、今回利用させていただきました。','会社の同僚が利用していて、とても対応が良くお値段も良いと紹介していただき、今回利用させていただきました。
発送までの流れが、少しわかりづらかったですが、値段も良く、発注することができたので、次回も利用したいと考えています。','4','/images/enquete/2024/1117_ttm_f.jpg','/images/enquete/2024/1117_ttm_dm.jpg'],['2024/7/8','/enquete/2024/','1118','826','oek','医療関連','東京都','1276','ご対応いただいた担当者様は、問い合わせに対して迅速に、丁寧に対応してくださり、とても安心できました。','1000～2000件の全国発送があり、これまでは、他社にて発送代行をお願いしておりました。その会社は、DM便代が高く、信書確認も時間がかなりかかるので、郵便で発送しており、その郵便代もかさむため、今回数社に見積を取り、検討しました。
数社の中で、御社が一番安かったわけではありませんでしたが、見積依頼後の迅速な返信とその後のフォロー(参考資料などをいただきました)が、いわゆる「痒い所に手が届く」内容で、御社にお願いすることに決めました。
ご対応いただいた担当者様は、問い合わせに対して迅速に、丁寧に対応してくださり、とても安心できました。また、信書確認も、とても早く、信書該当部分のアドバイスもしてくださり、大変助かりました。
今回の発送では、大きな経費節減となりました！御社に依頼して良かったです。','5','/images/enquete/2024/1118_oek_f.jpg','/images/enquete/2024/1118_oek_dm.jpg'],['2024/7/10','/enquete/2024/','1119','827','bsp','コンサルティング','東京都','1200','発送前までのご対応が強引な点もなく、ていねいで親切でした。','・なぜDM代行を利用したのか？
→新規開拓のため、1000件を超えることで自社発送よりも郵送代金を安くおさえられるため、メディアボックスさんを利用させていただいた。
・どうしてメディアボックスを選んだか？
→発注から発送までの期間が短くちょうど良かった点
→価格(おみつもり)もうちわけが分かりやすく判断がしやすかった点
・利用してよかった点
→発送前までのご対応が強引な点もなく、ていねいで親切でした。
→発送物の事前確認もあり、安心してあずけることができた。
→あてななどもサンプルがあり、分かりやすかったです。
ありがとうございました！(手書きが大変なので、このアンケートもネットで回答できると助かります)','4','/images/enquete/2024/1119_bsp_f.jpg','/images/enquete/2024/1119_bsp_dm.jpg'],['2024/7/21','/enquete/2024/','1120','828','rnt','美容関連','東京都','106','数社相見積させていただきましたが、断トツの価格で、尚かつ短い納期対応で、たいへん満足しています。','初めてのDM発送で、分からない事だらけだった。問い合わせに対応いただきありがたかったです。又、数社相見積させていただきましたが、断トツの価格で、尚かつ短い納期対応で、たいへん満足しています。
東京と愛知で距離の不安がありましたが、問題なかったです。途中のメールだけでなく、ハガキの連絡もありがたかったです。','4','/images/enquete/2024/1120_rnt_f.jpg','/images/enquete/2024/1120_rnt_dm.jpg'],['2024/7/22','/enquete/2024/','1121','829','hym','木材関連','神奈川','430','些細な質問にも親切に答えてくれました。
コスト面も少ない部数ではありましたが満足しています。','この度はありがとうございました。
スタッフ（長屋様）の対応が非常に迅速かつ丁寧で、些細な質問にも親切に答えてくれました。
コスト面も少ない部数ではありましたが満足しています。
また機会があれば利用させていただきます。','4','/images/enquete/2024/1121_hym_f.jpg','/images/enquete/2024/1121_hym_dm.jpg'],['2024/8/5','/enquete/2024/','1122','830','cra','広告資材関連','広島県','134','HPにうさんくささがなく、面倒な営業なども一切なく、見積りのメールも回答が早かったのでメディアボックス様を選びました。','初めてDMを出す業務を行うように指示があり、安価で安心できる代行業者様を探していました。出力をするのは自社で行えますが、その後の作業が大変な事が多いので様々な会社様を検索しました。
HPにうさんくささがなく、面倒な営業なども一切なく、見積りのメールも回答が早かったのでメディアボックス様を選びました。
要望への対応や料金の説明などがスムーズでわかりやすかったです。
データ送付から発送までのプロセスはとてもわかりやすく、初めての利用でも安心できました。また、サンプルもいただけて良かったです。','5','/images/enquete/2024/1122_cra_f.jpg','/images/enquete/2024/1122_cra_dm.jpg'],['2024/8/6','/enquete/2024/','1123','831','nsr','社団法人','東京都','493','価格が安かったのもありますが、1番の理由はご担当者様の顔がメールのやりとりで見えたような気がしたからです。対応のスピード感は大変早くとても助かりました。','・どうしてメディアボックスを選ばれたのですか？
価格が安かったのもありますが、1番の理由はご担当者様の顔がメールのやりとりで見えたような気がしたからです。対応のスピード感は大変早くとても助かりました。
・どうしてDM発送代行会社を利用しようと思ったのですか？
社内の人手が足らず、発送準備にも多くのコストをさかねばならず困ってたため
・メディアボックスを利用してよかった点はありますか？
メールの対応をしっかりとしてくださり助かりました。
また、進捗状況をご連絡いただけたので状況が把握しやすいと感じました。
安心して任せることができました。','4','/images/enquete/2024/1123_nsr_f.jpg','/images/enquete/2024/1123_nsr_dm.jpg'],['2024/8/6','/enquete/2024/','1124','832','sjd','大学','福岡県','1000','ネット見積もりからすぐにご担当の方からメールをいただき、作業工程やできあがりイメージなど細かく確認することができました。','今回、多機関に勤務する者同士での共同事業のための発送物をお願いしました。試しに見積もりをお願いした時に、県を跨いだ者が集まって作業する費用（交通費）よりも割安だったので利用させていただきました。見積もりで高価だったら、他業者も比較検討したと思いますが、それを行わずに済む価格でした。
ネット見積もりからすぐにご担当の方からメールをいただき、作業工程やできあがりイメージなど細かく確認することができました。最初の見積もりはゆうメールだったのですが、信書発送になることが分かり少し割高にはなりました。途中からオプションなどが付いてくるのでは…と少し不安もありましたが、印刷作業などの工程にかかる費用は、見積もり時からそれほど変わらずに済みました。
やり取りは主にメールでしたが、対応が迅速だったのと的確に答えていただいたのでありがたかったです。電話で確認させていただいた時も丁寧に答えていただきました。
サンプルや御礼ハガキ送付等もありがとうございました。
また何かの機会があればお願いしたいと思います。','4','/images/enquete/2024/1124_sjd_f.jpg','/images/enquete/2024/1124_sjd_dm.jpg'],['2024/8/9','/enquete/2024/','1125','833','ksk','医薬品関連','東京都','653','価格が他社様よりお安かった事、宛名ラベル貼りをデータ入稿のみで業務委託下さる事なども含め、お願いすることとしました。','この度はお世話になり有難うございました。
今回弊社としては初めてDM発送の試みでしたが、最初の問合せから分かりやすく、丁寧にご対応頂きました。
価格が他社様よりお安かった事、宛名ラベル貼りをデータ入稿のみで業務委託下さる事なども含め、お願いすることとしました。
発注～発送までの流れも、大変スムーズで細やかにご連絡を下さり、有難かったです。
また、機会がございましたらお願いしたいと思います。','5','/images/enquete/2024/1125_ksk_f.jpg','/images/enquete/2024/1125_ksk_dm.jpg'],['2024/8/9','/enquete/2024/','1126','834','mmh','コンサルティング','京都府','649','HPを見て安心感、価格等から選定しました。こちらの理解が不足している中、ていねいにご対応いただき大変感謝しております。','はじめてのサービス利用でどの会社がいいかも判らない中、当社担当者が何社か抽出してくれた中から選ばせていただきました。HPを見て安心感、価格等から選定しました。こちらの理解が不足している中、ていねいにご対応いただき大変感謝しております。
サービス利用の目的は当社で行うセミナー案内の発送です。','4','/images/enquete/2024/1126_mmh_f.jpg','/images/enquete/2024/1126_mmh_dm.jpg'],['2024/8/22','/enquete/2024/','1127','835','rlf','不動産関連','東京都','1986','作業時間の短縮、費用の軽減がありとても助かってます。','今までDMの作成から封筒の発注、封入作業まで自分達で行っていたので、作業時間の短縮、費用の軽減がありとても助かってます。
引き続き利用していきたいです。','5','/images/enquete/2024/1127_rlf_f.jpg','/images/enquete/2024/1127_rlf_dm.jpg'],['2024/8/22','/enquete/2024/','1128','836','tsp','コンサルティング','愛知県','1377','見積りがすばやく出てきて、営業電話などなく対応もていねいでした。','・見積りがすばやく出てきて、営業電話などなく対応もていねいでした。
・発送タイミングを相談して、納得して発送ができた。
・トータルで価格、内容ともに満足できるサービス内容でした。','5','/images/enquete/2024/1128_tsp_f.jpg','/images/enquete/2024/1128_tsp_dm.jpg'],['2024/8/28','/enquete/2024/','1129','837','epm','広告代理店','東京都','10000','見積依頼から終始対応が良く、やりとりがスムーズでした。','見積依頼から終始対応が良く、やりとりがスムーズでした。
細かい点にも対応してくれ、有難かったです。
また同様の案件の場合はぜひリピートさせて頂きます。
よろしくおねがいいたします！','5','/images/enquete/2024/1129_epm_f.jpg','/images/enquete/2024/1129_epm_dm.jpg'],['2024/9/2','/enquete/2024/','1130','838','nkk','気象関連','愛知県','100','メールだけでなく電話での問い合わせにもていねいに対応いただけ安心しておまかせできました。','従前は自社内にて人力でDM発送をしていたが、多くの時間を取られていました。そんな中、社内の他支社より、メディアボックスを紹介され、問い合わせました。すると即日で見積りをいただけ、価格も安かったためご依頼しました。メールだけでなく電話での問い合わせにもていねいに対応いただけ安心しておまかせできました。
引き続きよろしくお願いします。
ありがとうございました。','5','/images/enquete/2024/1130_nkk_f.jpg','/images/enquete/2024/1130_nkk_dm.jpg'],['2024/9/11','/enquete/2024/','1131','839','aks','スーパー','愛知県','260','発送作業に困り、メディアボックス様のお陰で想定よりも早く送る事ができ、大変感謝しております。','発送作業に困り、メディアボックス様のお陰で想定よりも早く送る事ができ、大変感謝しております。次回も何かあれば相談させて下さい。
ありがとうございました。','5','/images/enquete/2024/1131_aks_f.jpg','/images/enquete/2024/1131_aks_dm.jpg'],['2024/9/17','/enquete/2024/','1132','840','hen','太陽光発電関連','福島県','984','発注の流れも分かりやすくとてもスムーズでした。
分からない事も電話やメールで即対応してくださったので大変助かりました。','以前勤めていた会社で利用した事があり、その時も対応が良かった。
自分達で手作業発送は時間的に無理だと思いました。
発注の流れも分かりやすくとてもスムーズでした。
分からない事も電話やメールで即対応してくださったので大変助かりました。
また次回ＤＭ発送があれば利用したいと思います。','5','/images/enquete/2024/1132_hen_f.jpg','/images/enquete/2024/1132_hen_dm.jpg'],['2024/9/20','/enquete/2024/','1133','841','ese','産業機械関連','富山県','129','直筆のお葉書によるご案内などに誠意を感じ、料金の安さにもかかわらず、ここまでして頂ける会社はないと思って決めました。','20周年の記念誌を各所に送るために利用させて頂きました。150部足らずだったので、受けて頂けるかどうかと思いましたが、見積りの問い合わせ後すぐにサンプルを送って下さり、直筆のお葉書によるご案内などに誠意を感じ、料金の安さにもかかわらず、ここまでして頂ける会社はないと思って決めました。メールでの親切なご案内や、対応の早さにも驚いています。機会があれば、また利用させて頂きます。','5','/images/enquete/2024/1133_ese_f.jpg','/images/enquete/2024/1133_ese_dm.jpg'],['2024/9/22','/enquete/2024/','1134','842','isk','宗教関連','岩手県','475','印刷（今までは他者）から配送まで一括でお願いできて、非常に楽になりました。','ヤマト運輸のDM便の廃止で、配送物が滞っていました。今回少し配送料は上がりましたが、印刷（今までは他者）から配送まで一括でお願いできて、非常に楽になりました。
支払い方法にカード払いがあると助かります。','4','/images/enquete/2024/1134_isk_f.jpg','/images/enquete/2024/1134_isk_dm.jpg'],['2024/10/1','/enquete/2024/','1135','843','tyo','不動産関連','大阪府','516','たびたびの質問にもスムーズに返答いただき、不安を解消しながら進行出来たのが良かったです。','DMを送ることが初めてだったので、依頼から発送までの流れを教えていただきながら進めてもらいました。たびたびの質問にもスムーズに返答いただき、不安を解消しながら進行出来たのが良かったです。ホームページにも、DMに関する情報がたくさん掲載されていて、パンフレット作成時に迷うとき、判断材料になりとても助かりました。
この度はお世話になりありがとうございました。
また機会がありましたら宜しくお願い致します。','5','/images/enquete/2024/1135_tyo_f.jpg','/images/enquete/2024/1135_tyo_dm.jpg'],['2024/10/3','/enquete/2024/','1136','844','urt','コンサルティング','愛知県','305','今回急な依頼にも関わらず、迅速かつ丁寧にご対応頂き、大変たすかりました。','今回急な依頼にも関わらず、迅速かつ丁寧にご対応頂き、大変たすかりました。報連相もしっかりしていて、進める上で安心感がありました。また利用させて戴きます。','5','/images/enquete/2024/1136_urt_f.jpg','/images/enquete/2024/1136_urt_dm.jpg'],['2024/10/8','/enquete/2024/','1137','845','dis','教育関連','栃木県','2184','いろいろ紙の案内が届いたのですが、保管にも困りますので、PDF等データで頂く方がよかったように思います。','このたびはおせわになりました。
