質問への回答も早く、大変良かったです。
次回もよろしくお願いします。','5','/images/enquete/2024/1138_skt_f.jpg','/images/enquete/2024/1138_skt_dm.jpg'],['2024/11/2','/enquete/2024/','1139','847','mmj','県会議員','愛知県','8984','見積もりを取った時やメール対応等が丁寧だったのと値段が安いので、今回お願いしました。','以前お願いしていたDM発送業者とトラブルがあったため、新しい業者さんを探していました。見積もりを取った時やメール対応等が丁寧だったのと値段が安いので、今回お願いしました。以前の業者はこちらから連絡をしても担当の方が後からおり返しで連絡に時間がかかり、不手際もあったのですが、メディアボックスさんはTelしてもすぐに聞きたいことを教えていただけて、名簿の記入ミス等の連絡も頂けたので、助かりました。発送後も、発送済の連絡や引き渡し書の添付等、とても安心しておまかせすることができました。いろいろと無理を聞いて頂き、ありがとうございました。','4','/images/enquete/2024/1139_mmj_f.jpg','/images/enquete/2024/1139_mmj_dm.jpg'],['2024/11/7','/enquete/2024/','1140','848','sgm','ファイナンシャル・プランニング','愛知県','590','・サービス内容の表がこと細かに書かれており、利用側として安心感があった
・メールをすると返事がすぐにあり、細かいやりとりまでしていただいた','良かった点
・コストが他社と比べて非常に安い
・サービス内容の表がこと細かに書かれており、利用側として安心感があった
