・電話にもすぐでていただき、親切にご対応いただいた
・入口から出口までの真摯な対応に心打たれた
・愛知県の会社であるという安心感もあった
・売りこみがないのも良かった','5','/images/enquete/2024/1140_sgm_f.jpg','/images/enquete/2024/1140_sgm_dm.jpg'],['2024/11/11','/enquete/2024/','1141','849','hkb','病院','福岡県','520','御社はＤＭの反響を意識したレイアウトの例示を紹介していただいたり、お願いをしていなくても、サンプルを送付いただいたりして、制作や決裁をスムーズに行うことができました。','以前は他社にて、OPP封入のクロネコメールのDMを利用していました。今回、ゆう便の値上げや物価高騰のあおりを受けて、発送形態の見直しを行うことにし、A4ハガキサイズのDMに変更することにしました。他社では上部1/4が宛名に指定されていたり、左上に位置が固定されたりする中、御社はＤＭの反響を意識したレイアウトの例示を紹介していただいたり、お願いをしていなくても、サンプルを送付いただいたりして、制作や決裁をスムーズに行うことができました。また利用させていただこうと思います。ありがとうございました。','4','/images/enquete/2024/1141_hkb_f.jpg','/images/enquete/2024/1141_hkb_dm.jpg'],['2024/11/13','/enquete/2024/','1142','850','smk','コンサルティング','愛知県','400','印刷と配送を丸っと行ってくれる会社様を探していたところ、メディアボックスさんをネットで見つけました。','印刷と配送を丸っと行ってくれる会社様を探していたところ、メディアボックスさんをネットで見つけました。
丁寧な配送とご対応に感謝しております。
今後ともよろしくお願い致します。','5','/images/enquete/2024/1142_smk_f.jpg','/images/enquete/2024/1142_smk_dm.jpg'],['2024/11/26','/enquete/2024/','1143','851','hsi','印刷会社','東京都','1989','当方がとても不慣れで、いろいろお手数をおかけしたにもかかわらず、親切に対応して下さいました。','今回初めてゆうメール発送をしたため、当方がとても不慣れで、いろいろお手数をおかけしたにもかかわらず、親切に対応して下さいました。またご担当者様が明確で、いつ電話やメールしても、早急にお返事いただけたのも安心でした。今後もこういう仕事はお願いしたいです。','5','/images/enquete/2024/1143_hsi_f.jpg','/images/enquete/2024/1143_hsi_dm.jpg'],['2024/12/6','/enquete/2024/','1144','852','guj','園芸関連','東京都','212','初めての利用でしたが、情報データなど取扱いは丁寧な対応で安心しました。','初めての利用でしたが、情報データなど取扱いは丁寧な対応で安心しました。
ハガキやフォローなど心遣いをありがとうございました。
又利用させていただきたいと思います。','5','/images/enquete/2024/1144_guj_f.jpg','/images/enquete/2024/1144_guj_dm.jpg'],['2024/12/7','/enquete/2024/','1145','853','khs','コンサルティング','静岡県','348','印刷物、内容のサンプルもいただきましたがとてもていねいに作業していただいており他社とくらべてまったく遜色ない出来映えでした','DM作成に時間がかかり急ぎでなおかつ安価な代行業者をさがしネットにてヒットしたのが御社でした。見積り対応のスピードも早く我々の社内稟議もスムーズに進める事ができました。印刷物、内容のサンプルもいただきましたがとてもていねいに作業していただいており他社とくらべてまったく遜色ない出来映えでしたので次回こういったDM送付がある際はまたお願いしようかと思っています。','5','/images/enquete/2024/1145_khs_f.jpg','/images/enquete/2024/1145_khs_dm.jpg'],['2024/12/12','/enquete/2025/','1146','854','adk','衣装関連','東京都','1428','お見積りをはじめ、メールの対応が早く適格なので、安心して進める事が出来ました。','これまで自社でラベルを作成、封入、発送をしておりましたが、全てお任せしても、今までの金額よりも安くなり、びっくりしています。お見積りをはじめ、メールの対応が早く適格なので、安心して進める事が出来ました。注文数の変更にも素早く対応していただけて感謝しております。発送後も引き渡し書のPDFをいただけて、安心いたしました。次回も宜しくお願いいたします。','5','/images/enquete/2025/1146_adk_f.jpg','/images/enquete/2025/1146_adk_dm.jpg'],['2024/12/17','/enquete/2025/','1147','855','aks','保険代理店','神奈川','675','問い合わせ後すぐに見積りが届き、数日後には説明書類およびサンプルセットが届いたので、非常に助かりました。','この度はスムーズなご対応っをありがとうございました。
問い合わせ後すぐに見積りが届き、数日後には説明書類およびサンプルセットが届いたので、非常に助かりました。物品の送付や宛名データ入力に関してはルールがあり、初めてのためやや混乱する箇所もありましたが、電話でも質問にきちんと答えてくださり、安心してお取引きをすることができました。
DM等発送する際もかなりお安いようなので、ぜひまた利用させていただきたいと思います。
【アンケート項目への回答】
・毎年年末に500通以上の卓上カレンダーを送付しているのですが、昨年度より送料がかなり上がってしまい、安くなる方法を探していたところ、発送代行会社を利用した方が安いと知り、今年は依頼することにしました。
・いくつかの発送業者を比べましたが、メディアボックス様が一番お客様に寄り添ったサービスをしていると感じたため。
・安さはもちろん、レスポンスの速さ、フォローサービスが非常に良かったです。サンプルセットや御礼が届いて社内で皆びっくりしていました。','4','/images/enquete/2025/1147_aks_f.jpg','/images/enquete/2025/1147_aks_dm.jpg'],['2024/12/17','/enquete/2025/','1148','856','rde','人材派遣関連','愛知県','100','メディアボックス様はメールでのご対応が迅速丁寧で、やり取りに全く行き違いがなかったことで、安心してお任せすることができました。','今回、発送宛先数は多くはなかったのですが、日々の業務に追われており封入・宛名ラベル貼り作業の時間と手間を削減するためにDM発送代行会社を利用しようと思い、WEB検索で2社に絞り見積り依頼をかけまして、結果メディアボックス様にお願いすることにしました。
メディアボックス様はメールでのご対応が迅速丁寧で、やり取りに全く行き違いがなかったことで、安心してお任せすることができました。
また今回の封入物（チラシ）の内容が信書にあたり当方の都合でチラシ内容の修正ができなかったため発送方法をメール便から定形外郵便に変更させていただきましたが、そのご説明や作業も迅速で助かりました。
今後もDM発送の際はメディアボックス様を利用させていただきます。
1点だけ、当アンケートは郵送ではなくメールでいただいて記入返信、あるいはメールリンクでWEBフォームで回答入力の方が楽ですので、今後ご検討いただけますと幸いです。','5','/images/enquete/2025/1148_rde_f.jpg','/images/enquete/2025/1148_rde_dm.jpg'],['2024/12/18','/enquete/2025/','1149','857','aig','教育関連','東京都','1000','初めて聞く名前だったので不安もありましたが、対応が丁寧だったので安心できました。','今まで使っていたDM発送業者が大幅値上げしてしまったので、代わりの業者を探していたところ、メディアボックスが見つかりました。
初めて聞く名前だったので不安もありましたが、対応が丁寧だったので安心できました。というか、丁寧すぎてこちらが逆に恐縮してしまうほど。
発送数が980件でしたが、1000件にすると安くなると教えていただいたので、助かりました。980件でも1000件の値段にしてくれるサービスがあったら、お互い無駄がなくていいと思います。ありがとうございました。','5','/images/enquete/2025/1149_aig_f.jpg','/images/enquete/2025/1149_aig_dm.jpg'],['2024/12/19','/enquete/2025/','1150','858','agt','人材派遣関連','東京都','500','お送りいただいた書類に手書きのメッセージが添えられていたり、担当者の方の対応が親切かつ丁寧だったりと、安心してご依頼することができました。','初めて利用させていただきました。
お送りいただいた書類に手書きのメッセージが添えられていたり、担当者の方の対応が親切かつ丁寧だったりと、安心してご依頼することができました。
金額もお安く、少量での依頼も可能で、見積り発行も迅速で、大変助かりました。
今後も同様の業務が発生する際は、ご依頼させていただきたいと思います。','5','/images/enquete/2025/1150_agt_f.jpg','/images/enquete/2025/1150_agt_dm.jpg'],['2025/1/9','/enquete/2025/','1151','859','tcy','コンサルティング','新潟県','531','メールやハガキでひんぱんに連絡いただき、ていねいな対応と迅速な対応に感謝します。','メールやハガキでひんぱんに連絡いただき、ていねいな対応と迅速な対応に感謝します。
とても快かったので友達にも紹介しました。
またDM発送の際は使わせていただきますのでよろしくお願いします。','5','/images/enquete/2025/1151_tcy_f.jpg','/images/enquete/2025/1151_tcy_dm.jpg'],['2025/1/14','/enquete/2025/','1152','860','hyk','建設会社','神奈川県','600','ネットで代行会社を色々と探したところ、御社の口コミが良く、ホームページもわかりやすかったので、依頼させていただきました。','5年くらい前に一度別の代行会社を利用したことがあったのですが、データの入稿方法が面倒だったり、納期に融通が効かなかったりして、それ以降は自社で作業→メール便でやっていました。メール便単価改定に伴い、ネットで代行会社を色々と探したところ、御社の口コミが良く、ホームページもわかりやすかったので、依頼させていただきました。
入稿までも余裕があり、また入稿作業もとても楽でした。担当して下さった古澤様の対応も良かったです。
またお願いしたいと思いますので、よろしくお願いいたします。','5','/images/enquete/2025/1152_hyk_f.jpg','/images/enquete/2025/1152_hyk_dm.jpg'],['2025/1/17','/enquete/2025/','1153','861','yhs','建築関連','埼玉県','12000','年末の忙しい中の依頼でしたが、すぐに対応いただき、こちらの希望通りの納期で発送していただきました。大変感謝しております。','・どうしてDM発送会社に依頼しようと思ったか？
新商品の発売案内は社内で行っていたが、今回12,000剣と数が多かったので代行会社に依頼する事にしました。
・どうしてメディアボックスを利用しようと思ったか？
価格が安く、担当者がつくので安心してお任せできると思いました。
・利用してどうだったか？
年末の忙しい中の依頼でしたが、すぐに対応いただき、こちらの希望通りの納期で発送していただきました。大変感謝しております。
・気になる点
最初に送っていただいた資料一式の数が多かったのでもっとコンパクトにしていただけると良いと思いました。','5','/images/enquete/2025/1153_yhs_f.jpg','/images/enquete/2025/1153_yhs_dm.jpg'],['2025/01/18','/enquete/2025/','1154','862','arp','行政書士事務所','静岡県','1428','複数のDM会社と比較し価格、信頼度が良かったのでメディアボックス様にお願いすることにしました。','・複数のDM会社と比較し価格、信頼度が良かったのでメディアボックス様にお願いすることにしました。
・DM自体は集客方法の一つとして考えていて、一度試してみたかった。一度の発送で即効果がでるものではないので、二度、三度試して判断したい。
・メディアボックス様は、価格も安く、DMに関する知識、実績がとても優れていそうでしたのでお願いしました。発注から見積、案の作成、発送までとてもスムーズでした。','5','/images/enquete/2025/1154_arp_f.jpg','/images/enquete/2025/1154_arp_dm.jpg'],['2025/01/20','/enquete/2025/','1155','863','kon','出版社','東京都','653','本当にお世話になりました。
