ありがとうございます。','5','/images/enquete/2025/1155_kon_f.jpg','/images/enquete/2025/1155_kon_dm.jpg'],['2025/02/07','/enquete/2025/','1156','864','khs','訪問看護','神奈川県','792','コミュニケーションをこまめに取りながら、きちんと進めてくれたことはとても良かったと思います。','コミュニケーションをこまめに取りながら、きちんと進めてくれたことはとても良かったと思います。','4','/images/enquete/2025/1156_khs_f.jpg','/images/enquete/2025/1156_khs_dm.jpg'],['2025/02/07','/enquete/2025/','1157','865','ayk','会議施設','兵庫県','1890','お見積りの段階から親切にわかりやすく対応と説明下さり、時間のない中でもとてもスムースに社内処理が出来ました。','この度は、ありがとうございました。社内ではDM発送対応が難しいため代行会社を探しました。お見積りの段階から親切にわかりやすく対応と説明下さり、時間のない中でもとてもスムースに社内処理が出来ました。今後、年に一度は、当社広報誌を作成し発送する予定です。引き続きどうぞ宜しくお願い致します。
追記　予算に合せての部数調整を直前でも快く対応いただけて感謝しております。メディアボックスさんに決めたのは、料金もありますが、ご担当の対応がとても良かったからです。','5','/images/enquete/2025/1157_ayk_f.jpg','/images/enquete/2025/1157_ayk_dm.jpg'],['2025/02/13','/enquete/2025/','1158','866','kik','医療関連','東京都','601','お返事のスピードも早く、メールのやり取りも非常に丁寧で気持ちのよい取引をさせて頂きました。','お返事のスピードも早く、メールのやり取りも非常に丁寧で気持ちのよい取引をさせて頂きました。
また、機会がございましたら、よろしくお願いいたします。','5','/images/enquete/2025/1158_kik_f.jpg','/images/enquete/2025/1158_kik_dm.jpg'],['2025/03/08','/enquete/2025/','1159','867','ysz','テント関連','栃木県','47256','料金が他社よりも安く、今回のように部数が多くてもスムーズに発送作業をしていただき助かりました。','・今まで、他外注に封入、ラベル貼り等を依頼していたのですが、予定より作業が遅れるなどのトラブルがあり、DM代行業者を探していました。
・料金が他社よりも安く、今回のように部数が多くてもスムーズに発送作業をしていただき助かりました。
・今回、初めて利用させていただきましたが、見積を出していただくところから発送までの一連の流れを丁寧に電話、メール対応をしていただき迷うことなくこちらも下準備をすることができました。','4','/images/enquete/2025/1159_ysz_f.jpg','/images/enquete/2025/1159_ysz_dm.jpg'],['2025/03/23','/enquete/2025/','1160','868','hid','ダイビング関連','東京都','2081','御社は、サイトでの検索で上位にあった事と弊社の子会社が御社の利用経験があった事が決め手となりました。','今回は、新規事業立ち上げを各方面へ、アナウンスする為、DM発行代行を探していました。弊社の顧客の性質上、メールやWEBを使った広告ができなかった事も理由の1つです。
御社は、サイトでの検索で上位にあった事と弊社の子会社が御社の利用経験があった事が決め手となりました。
お見積の段階から最後まで、とても丁寧でわかりやすかったので助かりました。
ありがとうございました。','4','/images/enquete/2025/1160_hid_f.jpg','/images/enquete/2025/1160_hid_dm.jpg'],['2025/03/26','/enquete/2025/','1161','869','nsj','建設関連','東京都','255','外部への発注は初めてのことでしたので、流れなどが分からず、どうしたものか？と悩んでいましたが、貴社ご担当坂根様のスムーズなアテンドにより、業務依頼させていただきました。','この度はカタログ発送ありがとうございました。
外部への発注は初めてのことでしたので、流れなどが分からず、どうしたものか？と悩んでいましたが、貴社ご担当坂根様のスムーズなアテンドにより、業務依頼させていただきました。
最初の発注部数と次回以降の発注数量調整など、お得にしてもらえる提案をして頂きました。
見積り依頼、発注とその時々で自筆のお手紙を頂戴し、丁寧なお仕事ぶりが伺えました。
こちらからのメールでの連絡に対する返信報告が早く安心できます。
今後も機会があれば是非利用したいと思います。','5','/images/enquete/2025/1161_nsj_f.jpg','/images/enquete/2025/1161_nsj_dm.jpg'],['2025/03/26','/enquete/2025/','1162','870','nzr','宗教関連','愛知県','3141','・初めてのアポは電話連絡でしたが、丁寧な対応をいたたきありがたかったです。
','・これまで依頼していた業者が廃業してしまい、困っていた所で出会いました。
