・その後も担当者さんが最後までフォローしてくださったので、安心してお願いすることができました。
・発送前にはサンプルもわざわざ送付いただき、内容確認することができありがたかったです。
・次回以降も機会があればよろしくお願いします。','5','/images/enquete/2025/1162_nzr_f.jpg','/images/enquete/2025/1162_nzr_dm.jpg'],['2025/04/07','/enquete/2025/','1163','871','mni','金融関連','兵庫県','247','事前に資料をご提供いただけたことで、作業の流れや必要な準備が明確になり、スムーズに進められた点もありがたかったです。','こちらの細かな質問にも丁寧に答えていただき、安心してお任せできました。事前に資料をご提供いただけたことで、作業の流れや必要な準備が明確になり、スムーズに進められた点もありがたかったです。','5','/images/enquete/2025/1163_mni_f.jpg','/images/enquete/2025/1163_mni_dm.jpg'],['2025/04/11','/enquete/2025/','1164','872','rop','介護関連','大阪府','554','非常に丁寧に対応していただき安心してお願いできました。','非常に丁寧に対応していただき安心してお願いできました。
