DMに関する冊子等いただけて助かりました。','途中で担当者さんが変わりましたが、引継に問題なく対応していただけました。
DMに関する冊子等いただけて助かりました。
全体の流れとアップロードの手順（データ、名簿）は文章が長いと忙しいと読んでいるひまがないので、もう少し簡潔にしていただけると助かります。','5','/images/enquete/2025/1165_est_f.jpg','/images/enquete/2025/1165_est_dm.jpg'],['2025/04/16','/enquete/2025/','1166','874','isc','コンサルティング','兵庫県','500','価格が安く利用を検討しましたが、相見積りの中で最も分かり易く、対応も良く、最安ではありませんでしたが、DM施策をお願いしました。','大変お世話になりました。
