また利用させて頂く予定です。','5','/images/enquete/2025/1166_isc_f.jpg','/images/enquete/2025/1166_isc_dm.jpg'],['2025/04/18','/enquete/2025/','1167','875','aoi','広告代理店','東京都','2000','ご担当していただいた方がとても親切で、当社の都合でスケジュール通りいかない事情にも柔軟に対応いただきとても感謝しています。','ご担当していただいた方がとても親切で、当社の都合でスケジュール通りいかない事情にも柔軟に対応いただきとても感謝しています。
初めてのDM発送でしたが、今後もお願いしたいと思います。
メディアボックスを選んだ理由は、お見積依頼時のご対応がとても良かったからです。この会社におまかせしたいと思いました。','5','/images/enquete/2025/1167_aoi_f.jpg','/images/enquete/2025/1167_aoi_dm.jpg'],['2025/04/22','/enquete/2025/','1168','876','nhc','宝石関連','東京都','145','少部数でのDM発送代行業者を新たに探す事になったが、Web上で調べた結果、御社が一番信頼をおける内容であった。','毎月数万部単位でDMを発行しているが、今回テストで100部単位での臨時増刊号を出す事になった。少部数でのDM発送代行業者を新たに探す事になったが、Web上で調べた結果、御社が一番信頼をおける内容であった。
実際にお取引きを開始すると万事スムーズで何も問題はありませんでした。次回も利用させて頂きます。','5','/images/enquete/2025/1168_nhc_f.jpg','/images/enquete/2025/1168_nhc_dm.jpg'],['2025/04/30','/enquete/2025/','1169','877','nke','食品衛生管理','東京都','2278','ネットで御社を拝見し、お見積りをお願いしてみたところ、自社で行うよりも安く尚且つスピーディーに対応頂けることに驚きました。','毎年DMを全て自社で作成して発送しており、DMを発送する時期になると社員の負担増加や経費の圧迫が問題となっておりました。
そんな時にネットで御社を拝見し、お見積りをお願いしてみたところ、自社で行うよりも安く尚且つスピーディーに対応頂けることに驚きました。
担当の方の対応もとても丁寧で、問合せにすぐに返答のメールをくださったり、不安な点や疑問点にわかりやすく説明頂いたりと、安心してお願いすることが出来ました。ありがとうございました。','4','/images/enquete/2025/1169_nke_f.jpg','/images/enquete/2025/1169_nke_dm.jpg'],['2025/05/01','/enquete/2025/','1170','878','mbw','防災関連','岐阜県','896','価格が大変お値打ちで、自社でゆうメールで送付するより安かったのがとても助かりました。','価格が大変お値打ちで、自社でゆうメールで送付するより安かったのがとても助かりました。
また、メールでのやり取りも迅速に対応していただき有り難かったです。
ただ、2週間に一度の繰り返しの発送なので、部材到着日や宛名データ送信日の締め切りを問い合わせした際に日にちで教えてもらえたら更に有り難いなと思いました。','5','/images/enquete/2025/1170_mbw_f.jpg','/images/enquete/2025/1170_mbw_dm.jpg'],['2025/05/03','/enquete/2025/','1171','879','apa','市民講座','東京都','893','面倒な依頼のメールにも迅速に丁寧に対応して下さり、大変良かったです。','面倒な依頼のメールにも迅速に丁寧に対応して下さり、大変良かったです。
信書にあたるかどうかのチェック表など助かりました。
担当の方からはお葉書きまで頂き、とても丁寧な(御社の)対応に感心しました。','4','/images/enquete/2025/1171_apa_f.jpg','/images/enquete/2025/1171_apa_dm.jpg'],['2025/05/28','/enquete/2025/','1172','880','nbt','技能試験','東京都','182','発送も予定通りスムーズに行っていただき、進捗状況のご連絡もこまめにいただけて、安心してお取引できました。','2枚のチラシを1つの封筒に梱包発送する計画をしていましたが、他社ではその対応をしてもらえず、メディアボックスさんに依頼しました。対応がとても丁寧で、こちらの要望に迅速にご対応いただけました。発送も予定通りスムーズに行っていただき、進捗状況のご連絡もこまめにいただけて、安心してお取引できました。また機会がありましたら、よろしくお願いいたします。','4','/images/enquete/2025/1172_nbt_f.jpg','/images/enquete/2025/1172_nbt_dm.jpg'],['2025/05/30','/enquete/2025/','1173','881','pls','プラスチック製品製造','東京都','1320','ご担当いただいた坂根様にメールやお電話にて親切かつ迅速にご対応いただき、安心してお願いすることができました。','この度はDM郵送について円滑にご対応いただきましてありがとうございました。ご担当いただいた坂根様にメールやお電話にて親切かつ迅速にご対応いただき、安心してお願いすることができました。今後ともよろしくお願いいたします。','5','/images/enquete/2025/1173_pls_f.jpg','/images/enquete/2025/1173_pls_dm.jpg'],['2025/06/14','/enquete/2025/','1174','882','wnl','訪問看護','大阪府','500','連絡の対応の良さとフォローがよい。
ていねいな礼状を2回も頂いた。','取引先に一度に大量の資料を送付するにあたり、ネットで御社をみつけました。
連絡の対応の良さとフォローがよい。
ていねいな礼状を2回も頂いた。
今後共、よろしくお願い申し上げます。','4','/images/enquete/2025/1174_wnl_f.jpg','/images/enquete/2025/1174_wnl_dm.jpg'],['2025/07/01','/enquete/2025/','1175','883','hkj','フィットネス関連','広島県','560','今回初めての依頼でしたが事前のやりとりも丁寧でこちらの要望に柔軟に対応いただきました。発送後の管理も正確で予定通りにDMが届いたことでキャンペーンの反応率も上がりました。','これまで社内で対応していたDMの封入、発送作業に多くの時間と人手がかかっており課題でした。今回初めての依頼でしたが事前のやりとりも丁寧でこちらの要望に柔軟に対応いただきました。発送後の管理も正確で予定通りにDMが届いたことでキャンペーンの反応率も上がりました。コストパフォーマンスも良くまた機会があればお願いする予定です。プロに任せることで自社の業務に集中することができました。ありがとうございました。','5','/images/enquete/2025/1175_hkj_f.jpg','/images/enquete/2025/1175_hkj_dm.jpg'],['2025/07/02','/enquete/2025/','1176','884','kss','リフォーム関連','栃木県','200','御社を利用している方からの紹介だったので安心してお任せできたし、料金もお手頃だったので、結果お願いして良かったと思いました。','これまでは、自社内でチラシ折り→封入→切手貼りの作業を行っていましたが、手間がかかり切手代も上がったので、何とかできないものか？と思っていました。御社を利用している方からの紹介だったので安心してお任せできたし、料金もお手頃だったので、結果お願いして良かったと思いました。しかし、初めてなもので最初は流れがつかめず、マニュアルを読み込んだり、カレンダーとにらめっこして、印刷やリストの送付を進めるのに少々手こずりました。二度も手書きのハガキが届いたのは嬉しかったです。','5','/images/enquete/2025/1176_kss_f.jpg','/images/enquete/2025/1176_kss_dm.jpg'],['2025/07/13','/enquete/2025/','1177','885','oik','政治関連','沖縄県','6238','予算面や進行スケジュールなどマスト事項に関しても、常にタイムリーかつ明確な情報提供があり、スムーズに進行できました。','利用を検討したのは、発送作業の手間を削減する目的でした。
問い合せから非常に迅速かつ丁寧にご対応頂き、信頼感を持ちました。
予算面や進行スケジュールなどマスト事項に関しても、常にタイムリーかつ明確な情報提供があり、スムーズに進行できました。
全体を通して、とても利用しやすく、今後も継続的にお願いしたいと思っています。','5','/images/enquete/2025/1177_oik_f.jpg','/images/enquete/2025/1177_oik_dm.jpg'],['2025/07/18','/enquete/2025/','1178','886','ksn','貴金属関連','東京都','10000','最初にお電話で問い合わせをした際も、ご対応がとても丁寧で安心感がありました。
複雑な依頼内容についても、迅速にご確認・ご対応いただき、大変助かりました。','今回、初めてDM発送をお願いさせていただきました。
最初にお電話で問い合わせをした際も、ご対応がとても丁寧で安心感がありました。
複雑な依頼内容についても、迅速にご確認・ご対応いただき、大変助かりました。
実際の依頼においても、不明点があれば気軽に質問でき、毎回丁寧にご説明いただきました。
メールでのやり取りもスムーズで、細かな確認にも迅速にご対応いただき感謝しています。
社内でも「依頼してよかった」との声が上がっており、今後もお願いしたいと思っております。','3','/images/enquete/2025/1178_ksn_f.jpg','/images/enquete/2025/1178_ksn_dm.jpg'],['2025/07/24','/enquete/2025/','1179','887','ssb','美容関連','愛媛県','1103','問い合わせして、資料請求した時の資料が細かくわかりやすかったので、メディアボックスさんを使用する事に決めました。','問い合わせして、資料請求した時の資料が細かくわかりやすかったので、メディアボックスさんを使用する事に決めました。
入金がない、確認できたなどタイムリーに報告を頂いたことでミスなくできました。
修正箇所を教えて頂いた事も良かったです。
又使用すると思います。','5','/images/enquete/2025/1179_ssb_f.jpg','/images/enquete/2025/1179_ssb_dm.jpg'],['2025/08/01','/enquete/2025/','1180','888','awi','通信販売','埼玉県','200','費用対効果を考えると自分の手で費用を抑えてDMを作ることはできましたが、発送経費が意外に掛かるという壁です。インターネット検索で絞り込んだのが「メディアボックス」の発送のみという項目です。更に郵送で20％以上も節約が可能ならば利用するしかない。','無店舗卸販売の不利な出発を補う方法として考えたのが、昔ながらの行商です。しかしながら、誠意と口コミで「商品取り扱い店舗を開拓」は時間と交通費などの費用がかさみ、続けられそうにない。大手流通の販促に乗った販売では、新規売り込みはお断りの店舗も増え商談も難しいのが現状です。SNSのフィッシング広告は万能ではありません。そう考えると、手にとって興味を抱かせる広告の「DM発送」で様子を見てみよう。と思いDM広告を決めました。費用対効果を考えると自分の手で費用を抑えてDMを作ることはできましたが、発送経費が意外に掛かるという壁です。インターネット検索で絞り込んだのが「メディアボックス」の発送のみという項目です。更に郵送で20％以上も節約が可能ならば利用するしかない。
交通費・発送費の節約が主な目的でしたので、目的達成です。今後も利用させていいただきま。','4','/images/enquete/2025/1180_awi_f.jpg','/images/enquete/2025/1180_awi_dm.jpg'],['2025/08/05','/enquete/2025/','1181','889','rbr','服飾関連','東京都','500','柔軟にかつ丁寧にご対応くださった姿勢には、感謝しかありません。誠実で迅速なご対応の数々が、安心してお任せできる要因となりました。','この度は、心のこもった対応を誠にありがとうございました。
とくに印象的だったのは、2度にわたってお礼のお葉書をいただいた点です。お心遣いが嬉しく、信頼感がより深まりました。また、メール対応が多い中で、わからない点を電話で丁寧に教えていただけたことも大変助かりました。
さらに、時間的に余裕がない中での急な依頼にもかかわらず。柔軟にかつ丁寧にご対応くださった姿勢には、感謝しかありません。誠実で迅速なご対応の数々が、安心してお任せできる要因となりました。今後もぜひお願いしたいと思っております。','4','/images/enquete/2025/1181_rbr_f.jpg','/images/enquete/2025/1181_rbr_dm.jpg'],['2025/08/05','/enquete/2025/','1182','890','kdf','介護関連','奈良県','500','IT化が進んできたとは言え、まだまだ大切なことは郵送でないといけない事があります。当方高齢者介護サービスを展開してます故、また利用することがあれば、よろしくお願い致します。','今回の郵送等業務受注頂きありがとうございました。
KAERU株式会社様からの紹介で発注させて頂きました。
IT化が進んできたとは言え、まだまだ大切なことは郵送でないといけない事があります。当方高齢者介護サービスを展開してます故、また利用することがあれば、よろしくお願い致します。','4','/images/enquete/2025/1182_kdf_f.jpg','/images/enquete/2025/1182_kdf_dm.jpg'],['2025/08/06','/enquete/2025/','1183','891','sbm','医療関連','千葉県','259','3.メディアボックス様を利用させていただいて良かった点
①メール対応が丁寧、迅速、確実で、とても安心してお取引できました。
②価格も、印刷だけを他社と比較すると少し高いですが、印刷～発送までトータルで考えると安いと思います。
③印刷・封入・封緘・宛名ラベル貼の品質はとても良かったです。
④印刷データチェック完了～発送までのリードタイムがとても短いと思います。
⑤料金後納郵便物差出票の送付、宛名データ削除証明の送付、返品物EXCELデータ化を追加料金なしで実施してくださるのも良心的です。','1.DM発送代行会社を利用した理由
当会は病気の患者団体で、1年に数回の頻度で会報(A4中綴じ冊子)を発行しています。
以前は印刷会社様から納品された冊子を、角2封筒封入・封緘・宛名ラベル貼・発送まで自力で行っていましたが、病人にとっては重労働であるため、数年前からネット印刷会社様のDMサービスを利用していました。
2.メディアボックス様を選んだ理由
他社様のDMサービスには以下のような問題がありました。
①発送量が少ないと請け負ってもらえない。
②封入物が20ページ以上のA4中綴じ冊子だと請け負ってもらえない。
③印刷～DM発送までワンストップで請け負ってもらえない。
④角2封筒だと請け負ってもらえない。
ネットで検索して何社か問合せしましたが、上記の問題を全てクリアして請け負っていただけたのはメディアボックス様だけでした。
3.メディアボックス様を利用させていただいて良かった点
①メール対応が丁寧、迅速、確実で、とても安心してお取引できました。
②価格も、印刷だけを他社と比較すると少し高いですが、印刷～発送までトータルで考えると安いと思います。
③印刷・封入・封緘・宛名ラベル貼の品質はとても良かったです。
④印刷データチェック完了～発送までのリードタイムがとても短いと思います。
⑤料金後納郵便物差出票の送付、宛名データ削除証明の送付、返品物EXCELデータ化を追加料金なしで実施してくださるのも良心的です。
また注文させていただきたいと思いますので、今後ともよろしくお願い申し上げます。','5','/images/enquete/2025/1183_sbm_f.jpg','/images/enquete/2025/1183_sbm_dm.jpg'],['2025/08/27','/enquete/2025/','1184','892','mjk','車関連','福島県','4652','とりあえず見積りの依頼をしたら、すぐに返信が来て、金額にビックリ‼後日、会社の案内DMがきて、内容を見るとそのクオリティが高いことを確信できたので、安心して発注することができました。','ニュースレターを始めるにあたり、65年の歴史があるため部数が、約5000部であることが分かり、作業や印刷段取り等を考えただけで挫折しそうになってました。ネットで、どんな業社があるのか、検索していたところ、メディアボックスさんを知り、とりあえず見積りの依頼をしたら、すぐに返信が来て、金額にビックリ‼後日、会社の案内DMがきて、内容を見るとそのクオリティが高いことを確信できたので、安心して発注することができました。
担当の方のレスポンスや説明も素晴らしくたのんで良かったです。今後ともよろしくお願いします。','5','/images/enquete/2025/1184_mjk_f.jpg','/images/enquete/2025/1184_mjk_dm.jpg'],['2025/09/02','/enquete/2025/','1185','893','iks','建築関連','滋賀県','200','発注から発送までの時間が短いのと単価が安いとウワサで聞いておりました。
ただ実際に注文させて頂き、対応の早さと後日の確認アプローチも丁寧で安心感につながっています。','今回はご連絡ありがとうございます。
又先日はDM発送ありがとうございました。
発注から発送までの時間が短いのと単価が安いとウワサで聞いておりました。
ただ実際に注文させて頂き、対応の早さと後日の確認アプローチも丁寧で安心感につながっています。
目に見えない形での発注業務なので、信頼するしかありません。
発送直前の実物写真や発送記録などがあるとともっと安心できると思います。
又是非依頼したいと思いますので、今後もよろしくお願い致します。','4','/images/enquete/2025/1185_iks_f.jpg','/images/enquete/2025/1185_iks_dm.jpg'],['2025/09/05','/enquete/2025/','1186','894','ibk','板金関連','新潟県','400','毎回、いろいろな確認や報告を丁寧なメール対応でしてくださり、安心してお願いすることができました。','紹介で御社に発送業務をお願いしました。
