他の業者さんと比較していないので、金額等が実際にどうかはわかりませんが、それ以前に大変信頼できる会社だと思ったので、今後共、お願いしたいと考えています。','5','/images/enquete/2025/1186_ibk_f.jpg','/images/enquete/2025/1186_ibk_dm.jpg'],['2025/09/24','/enquete/2025/','1187','895','tkj','会計士事務所','東京都','2338','クロネコのゆうメールが利用できた時期は自社内でDMを封入して送っていましたが、コスト面から見てもご依頼した方が安く、今回お仕事をお願いした次第です。','インターネットで「DM」と検索しますと、いろいろな業者さまが出ておられましたが、比較サイトの中に御社の紹介が出ておりました。
HPへ見に行きますとDMについての情報がたくさん出ておりまして、大変勉強になりました。クロネコのゆうメールが利用できた時期は自社内でDMを封入して送っていましたが、コスト面から見てもご依頼した方が安く、今回お仕事をお願いした次第です。
