依頼時も色々とご対応いただきスムーズに業務が進み大変助かります。
今後も依頼したい件が残ってるので、引き続きよろしくお願いいたします。','5','/images/enquete/2025/1192_nfk_f.jpg','/images/enquete/2025/1192_nfk_dm.jpg'],['2025/10/09','/enquete/2025/','1193','901','mdj','医療機器関連','東京都','1019','見積もり依頼から発送リストの確認、発送まで非常に迅速できめ細やかなご対応をいただきましたので、非常に安心してお任せすることが出来ました。','見積もり依頼から発送リストの確認、発送まで非常に迅速できめ細やかなご対応をいただきましたので、非常に安心してお任せすることが出来ました。
同時進行で別件のご依頼相談に対しても、少々ややこしい内容でしたがすぐにご回答をいただき、従前利用していた業者と比較にならない安心感と対応スピードはとても好感が持て、今後もぜひともお願いしたいと思っています。','5','/images/enquete/2025/1193_mdj_f.jpg','/images/enquete/2025/1193_mdj_dm.jpg'],['2025/10/17','/enquete/2025/','1194','902','nbk','システム開発','熊本','1333','価格はもちろんですが、サンプルの豊富さやメールでの対応の丁寧さが決め手となり、この度御社に印刷・発送業務をお願いすることになりました。','以前は別の業者さまにDM印刷・発送をお願いしていました。
