郵送頂いた書類もわかりやすく、安心してお任せすることが出来ました。','今回、初めての対応でしたが、電話・メールでの対応が丁寧であること、
郵送頂いた書類もわかりやすく、安心してお任せすることが出来ました。どのような会社なのかが、一番はじめの郵送案内でよく理解することが出来たのも、とても良かったです。
ホームページ＋郵送案内がわかりやすいため、他者にも説明しやすく、ありがたかったです。','5','/images/enquete/2025/1195_hml_f.jpg','/images/enquete/2025/1195_hml_dm.jpg'],['2025/11/19','/enquete/2025/','1196','904','nsd','教育関連','新潟県','5000','発送にかかる送料の実費を考えると、代行作業料も安価で、値段とサービスを考えると大変コストパフォーマンスのよい会社で、安心してお願いすることができました。','調査研究の発送作業の代行業者を探していました。地元の業者も含めて数社に見積もり等の依頼を行いましたが、地元の業者よりも対応が早く、丁寧でした。メールでの対応が基本でしたが、こちらも電話に対応できる時間が不規則なため、助かりました、
発送にかかる送料の実費を考えると、代行作業料も安価で、値段とサービスを考えると大変コストパフォーマンスのよい会社で、安心してお願いすることができました。　ありがとうございました。','4','/images/enquete/2025/1196_nsd_f.jpg','/images/enquete/2025/1196_nsd_dm.jpg'],['2025/11/25','/enquete/2025/','1197','905','kin','翻訳関連会社','東京都','1483','メール対応や不明点への回答など、とてもスピーディに解りやすく、御社へお願いしてよかったと思っております。','普段は社内でデザイン作成→印刷→ラベルはり→発送を行っていましたが、DM費の予算が取れる案件だったため依頼させて頂きました。
chatGTPに複数候補を出してもらい、そこから各サイトを確認し、安心感を感じられたため御社を選択させて頂きました。
メール対応や不明点への回答など、とてもスピーディに解りやすく、御社へお願いしてよかったと思っております。
反応率の高い施策ではないため、費用対効果を高めていく工夫も今後学ばせて頂ければと思います。ありがとうございました。','5','/images/enquete/2025/1197_kin_f.jpg','/images/enquete/2025/1197_kin_dm.jpg'],['2025/11/25','/enquete/2025/','1198','906','ffm','医療機器関連','徳島県','326','社内でメディアボックスを知っている者がおり、案内して相談することができました。部数・期間、そして当日の集客も予想以上にあり、利用させてきただき本当に良かったと思っています。','先日は、封入・封かんで利用させていただき、お世話になりました。
セミナー開催にあたり、会社内担当者全員での声かけにより集客を願いましたが、多数の集客を見込めなく、急きょ案内状及びチラシの封入・封かんを依頼しました。会社内での準備に時間がなく、また不慣れな中作業するよりも、専門の方々へ依頼した方が効率的と判断し依頼させていただきました。
封入・封かんといえば、郵便局と思いましたが、手続きに時間がかかり、安価ではないと聞いていました。社内でメディアボックスを知っている者がおり、案内して相談することができました。部数・期間、そして当日の集客も予想以上にあり、利用させてきただき本当に良かったと思っています。やりとりや連絡に時間を割く事なく、スムーズで利用しやすかったです。また機会がありましたら利用させていただきます。','5','/images/enquete/2025/1198_ffm_f.jpg','/images/enquete/2025/1198_ffm_dm.jpg'],['2025/11/29','/enquete/2025/','1199','907','sry','情報通信サービス','東京都','347','参考を送付していただいたり、ご連絡が早かったり等、ユーザーが不安に思う点をすべて解消してくださるのが、とても安心して取引できました。','お世話になります。この度は、迅速でご丁寧な対応をいただき、誠にありがとうございました。
①弊社では、商品訴求のDM施策がありますが、人手不足により、代行会社を利用しています。
➁複数の会社に見積依頼をしましたが、一番安く、なによりご丁寧に対応いただけたからです。また、他社へ依頼していた際は、入稿ルール　(データ形式や方法など)が複雑でしたが貴社は、一番簡単でした。
③参考を送付していただいたり、ご連絡が早かったり等、ユーザーが不安に思う点をすべて解消してくださるのが、とても安心して取引できました。都度、ご丁寧なお手紙をいただいておりましたが、従業員様のご負担が少し気になるくらいです。皆様ご自愛くださいませ。引き続きよろしくお願いします。','5','/images/enquete/2025/1199_sry_f.jpg','/images/enquete/2025/1199_sry_dm.jpg'],['2025/12/03','/enquete/2025/','1200','908','set','通信機器販売','東京都','500','今回短いスケジュールの中でのお願いでしたが進行状況についてもこまめにご連絡をいただいた為、安心してお任せすることができました。','この度はDMの封入封緘および郵送作業につきまして丁寧かつ迅速にご対応いただき誠にありがとうございました。
