作業の段取りやご説明も分かりやすく、こちらの要望にも柔軟にご対応いただき大満足です。
今後もまた機会がありましたらぜひよろしくお願いいたします。','5','/images/enquete/2025/1200_set_f.jpg','/images/enquete/2025/1200_set_dm.jpg'],['2025/12/08','/enquete/2025/','1201','909','tgp','税理士事務所','大阪府','14435','15パターンという、複雑な封入作業にも関わらず、ご対応いただけた事、メール、電話の対応も、わかりやすかったです。
何より1番は、とてもレスポンスが早く、感動いたしました。','➁元々依頼予定だった業者とのスケジューリングがあわず、Webで検索していた所、複数パターンの封入が可能となっていた為
①1万件超の発送を行うため
③最初に問合せした時に、対応してくださった坂根さんが、そのまま最後まで対応して下さり安心でした。
また、15パターンという、複雑な封入作業にも関わらず、ご対応いただけた事、メール、電話の対応も、わかりやすかったです。
何より1番は、とてもレスポンスが早く、感動いたしました。
お忙しい中、ありがとうございました。','5','/images/enquete/2025/1201_tgp_f.jpg','/images/enquete/2025/1201_tgp_dm.jpg'],['2025/12/15','/enquete/2025/','1202','910','sri','税理士事務所','大阪府','1150','宛名データのシート名とリストがズレていたのですが、担当者様の作業前チェックでご指摘いただき、誤発注を防ぐことができました。','実は発注の際、宛名データのシート名とリストがズレていたのですが、担当者様の作業前チェックでご指摘いただき、誤発注を防ぐことができました。
改めて感謝申し上げます。','5','/images/enquete/2025/1202_sri_f.jpg','/images/enquete/2025/1202_sri_dm.jpg'],['2026/01/05','/enquete/2026/','1203','911','til','不動産関連','大阪府','232','他業務が、忙しく、なかなか手がつけれず、見積りをして頂いた所でとまってましたが、その間ひつこく電話がかかってくることもなく、嫌なイメージが、１つもありませんでした。','DM代行を探していた中、一番早く対応していただき、見積りをだして頂きました。
その後、他業務が、忙しく、なかなか手がつけれず、見積りをして頂いた所でとまってましたが、その間ひつこく電話がかかってくることもなく、嫌なイメージが、１つもありませんでした。少し業務がおちつき、業者様をあらためて選ぶときに、どうしても、しつこく電話をしてきていた業者を選ぶ気になれませんでした。その時、御社から送付されていた、見本一式が目に入り、メールで、もう一度問い合わせたところ、数ヵ月空いていたにもかかわらず、すぐにお返事がきました。そのスピード感がとても業務をするにあたって信頼できると思いました。毎月の依頼になるので、引き続きお世話になりますが、よろしくおねがいします。','4','/images/enquete/2026/1203_til_f.jpg','/images/enquete/2026/1203_til_dm.jpg'],['2026/01/09','/enquete/2026/','1204','912','csi','不動産関連','大阪府','260','・メディアボックスは相談した際に返事が早く丁寧だった
・お手紙は嬉しかったです','・会社を設立してⅠ人で活動しているので、集客にはDMを活用するしかない
・大手他社と金額を比較してメディアボックスが安かったため
・当初大手を検討しており、オンラインで手続きを進めていたが、発送先データを投稿するところでエラーが出て、相談できるところもよくわからなかったので止めた
・メディアボックスは相談した際に返事が早く丁寧だった
・お手紙は嬉しかったです
・投稿から発送までは他社の方が速かったですが、今度はメディアボックスの進め方で準備をしようと考えています','5','/images/enquete/2026/1204_csi_f.jpg','/images/enquete/2026/1204_csi_dm.jpg'],['2026/01/29','/enquete/2026/','1205','913','tmr','医療関連','新潟県','2110','複数社からお見積をいただく中で、価格が最も安く、ホームページから信頼できると感じたため、メディアボックス様へ依頼させていただきました。','これまで自社で対応していたDM発送について、今回は部数増加とビニール封津での発送希望があり、DM代行業者を探しておりました。
複数社からお見積をいただく中で、価格が最も安く、ホームページから信頼できると感じたため、メディアボックス様へ依頼させていただきました。
資料送付や丁寧なお葉書のご対応もあり安心してお願いできました。
年末のご多忙な時期(しかも最終営業日まで)発送日を早めたいという要望に親切にご対応いただき大変助かりました。
今後もDM発送の際はぜひメディアボックス様へお願いしたいと思います。
一方で到着確認できる仕組みがあると大変ありがたいと感じました。
また初回だけではなく、毎回サンプルをいただけると、より安心できると思います。
(こちらの説明が十分にお伝えできているか不安な為)','5','/images/enquete/2026/1205_tmr_f.jpg','/images/enquete/2026/1205_tmr_dm.jpg'],['2026/02/16','/enquete/2026/','1206','914','hyk','外壁塗装','愛知県','2659','どんなささいなことでも担当の方にお伺いするとすぐに返信があり、安心して進めることができました。','これまでDM発送は封入・あて名シール貼り、ゆうびん局への差出まですべて自社で行っていました。今回初めて御社でお願いするにあたり、あて名の提出や差出など不安がありましたが、どんなささいなことでも担当の方にお伺いするとすぐに返信があり、安心して進めることができました。ありがとうございました。今後もメディアボックス様にお願いしたいと考えております。','5','/images/enquete/2026/1206_hyk_f.jpg','/images/enquete/2026/1206_hyk_dm.jpg'],['2026/02/19','/enquete/2026/','1207','915','tft','飲食業','東京都','903','問い合わせへの返信が非常に早く、不明点にも明確にご対応いただき安心感がありました。やり取りが終始スムーズで、信頼してお任せすることができました。','価格改定という重要なお知らせの発送だったため、正確性とスピード感を重視して依頼先を検討しました。
小ロットにも柔軟に対応していただける点と、見積依頼時のご対応が迅速かつ、どういった流れになるのか事前説明が分かりやすかったことが決め手です。
その後問い合わせへの返信が非常に早く、不明点にも明確にご対応いただき安心感がありました。やり取りが終始スムーズで、信頼してお任せすることができました。
進行が滞ることなく完了でき、大変助かりました。
重要な発送物をストレスなく進められたことに感謝しております。','5','/images/enquete/2026/1207_tft_f.jpg','/images/enquete/2026/1207_tft_dm.jpg'],['2026/02/27','/enquete/2026/','1208','916','itp','葬儀関連','東京都','100','選んだ理由は価格の安さです。
作業の負担がなくなったのが一番良かったです。','これまで自社内で封入作業をしていましたが作業が負担を感じていため。
選んだ理由は価格の安さです。
作業の負担がなくなったのが一番良かったです。
発送数が少なかったので他社に断られて困っていました。
また利用させていただきます。','5','/images/enquete/2026/1208_itp_f.jpg','/images/enquete/2026/1208_itp_dm.jpg'],['2026/02/28','/enquete/2026/','1209','917','nsb','社団法人','東京都','4340','実際に利用させていただいて、とてもスピーディで、対応も丁寧なところには、感動しました。','メディアボックスさんを選んだ理由は、知りあいのしょうかいです。
実際に利用させていただいて、とてもスピーディで、対応も丁寧なところには、感動しました。初めてのDM郵送となりますが、メディアボックスさんに頼んで良かったと感じています。
引き続き今後も利用させていただきます。','5','/images/enquete/2026/1209_nsb_f.jpg','/images/enquete/2026/1209_nsb_dm.jpg'],['2026/03/06','/enquete/2026/','1210','918','rng','製造業','愛知県','1158','メディアボックスを利用して良かった点は、細かい事でも、メールをしてすぐに返信をいただけ、また、丁寧な返信でとても信頼感が持てました。','メディアボックスを利用して良かった点は、細かい事でも、メールをしてすぐに返信をいただけ、また、丁寧な返信でとても信頼感が持てました。発送作業についても、短納期にもかかわらず、迅速に対応いただき、大変助かりました。唯一改善を期待したい点としては、発送元などの表記があまり自由度が高くなかった点です。規則等があるのかもしれませんが、可能ならばその点を改善いただければ、より良いと思いました。ありがとうございました。','4','/images/enquete/2026/1210_rng_f.jpg','/images/enquete/2026/1210_rng_dm.jpg'],['2026/03/16','/enquete/2026/','1211','919','dks','出版業','東京都','378','印刷から宛名対応、封入・発送まで、アッセンブリー作業を含めてまとめてお願いできたことで、社内の手間も大きく軽減されました。','毎年、創立記念日にあわせて取引先の皆様へ花の種をお送りしています。
日頃の感謝の気持ちを、ささやかな形でお届けしたいという思いから続けている取り組みです。

今回は、メッセージカードの印刷や宛名対応、花の種の封入・発送などの作業をどのように進めるか悩んでいたところ、メディアボックス様にご相談でき大変助かりました。印刷から宛名対応、封入・発送まで、アッセンブリー作業を含めてまとめてお願いできたことで、社内の手間も大きく軽減されました。細かな要望にも丁寧に対応していただき、安心して進めることができました。

料金も明朗で分かりやすく、費用面でも良心的だと感じています。今後も同様の業務がある際には、ぜひまたお願いしたいと思っています。','5','/images/enquete/2026/1211_dks_f.jpg','/images/enquete/2026/1211_dks_dm.jpg'],['2026/03/19','/enquete/2026/','1212','920','sge','学校法人','東京都','1468','全体的な評価としては非常に満足しており、特に見積もりから発注に至るまでのスピード感と、コストパフォーマンスの高さには驚かされました。','今回、販促キャンペーンのDM発送にあたり「DM発送代行センター」を利用させていただきました。全体的な評価としては非常に満足しており、特に見積もりから発注に至るまでのスピード感と、コストパフォーマンスの高さには驚かされました。

しかし、唯一今後の改善を期待したい点として、「発送前の入金タイミング」が挙げられます。現在は入金確認が取れてからの発送準備・投函という流れが徹底されていますが、ビジネスの現場では社内の決済フローや急なスケジュール変更により、どうしても入金が数日タイトになってしまう場面があります。','3','/images/enquete/2026/1212_sge_f.jpg','/images/enquete/2026/1212_sge_dm.jpg'],['2026/03/19','/enquete/2026/','1213','921','ser','観光関連','北海道','208','初めての依頼で、不安やわからない点も多かったため事前に何度も相談にのっていただきました。','初めての依頼で、不安やわからない点も多かったため事前に何度も相談にのっていただきました。
細かい点にも丁寧に返答、対応いただきとても感謝しています。
価格的にも自社で行うよりも大変安く、助かりました。','5','/images/enquete/2026/1213_ser_f.jpg','/images/enquete/2026/1213_ser_dm.jpg'],['2026/03/27','/enquete/2026/','1214','922','imw','医療関連','大阪府','767','見積書の作成やメールの返信など、スピーディーに対応していただき助かりました。進行中も担当の方からこまめにご連絡をいただけたため、終始安心してお任せすることができました。','貴社に依頼したきっかけは、日頃から取引のある企業様からのご紹介でした。
実際にお願いしてみて、まず価格が非常にリーズナブルであったことに大変満足しております。また、見積書の作成やメールの返信など、スピーディーに対応していただき助かりました。進行中も担当の方からこまめにご連絡をいただけたため、終始安心してお任せすることができました。ぜひ次回もお願いしたいと考えております。
一点、今後のご要望としてお伝えしたいのが、印刷データなどの入稿方法についてです。
現在はメールでの提出となっておりますが、データ容量が重くなることも多いため、少し手間に感じております。Web上でのファイルアップロード機能などがあると、より簡便で助かります。
今後のサービス向上に期待しつつ、引き続きよろしくお願いいたします。','5','/images/enquete/2026/1214_imw_f.jpg','/images/enquete/2026/1214_imw_dm.jpg'],
];
